import type { BankQuestion } from "@/lib/bank";

/** Child Development and Pedagogy (Child Development and Pedagogy): 250 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"cdp-child-development-1","question":"The RTE Act, 2009 provides free and compulsory education for children aged:","options":["3–14 years","6–14 years","6–18 years","5–15 years"],"answer":1,"explanation":"It covers children aged 6 to 14.","difficulty":"easy"},
  {"id":"cdp-child-development-2","question":"RTE stands for:","options":["Right to Education","Rules of Teaching Excellence","Right to Employment","Reading, Teaching and Evaluation"],"answer":0,"explanation":"The Right of Children to Free and Compulsory Education Act, 2009.","difficulty":"easy"},
  {"id":"cdp-child-development-3","question":"Which thinker is associated with the stages of cognitive development?","options":["Jean Piaget","B. F. Skinner","Ivan Pavlov","Sigmund Freud"],"answer":0,"explanation":"Piaget described four stages of cognitive development.","difficulty":"easy"},
  {"id":"cdp-child-development-4","question":"The concept of the Zone of Proximal Development was given by:","options":["Piaget","Vygotsky","Kohlberg","Skinner"],"answer":1,"explanation":"Lev Vygotsky introduced the ZPD: what a learner can do with help but not yet alone.","difficulty":"moderate"},
  {"id":"cdp-child-development-5","question":"The theory of multiple intelligences was proposed by:","options":["Howard Gardner","Jean Piaget","Lawrence Kohlberg","B. F. Skinner"],"answer":0,"explanation":"Howard Gardner proposed it in 1983.","difficulty":"moderate"},
  {"id":"cdp-child-development-6","question":"The term “scaffolding” in learning is associated with:","options":["Piaget","Vygotsky","Kohlberg","Erikson"],"answer":1,"explanation":"Scaffolding, temporary support from a more capable person, comes from Vygotsky’s sociocultural theory.","difficulty":"moderate"},
  {"id":"cdp-child-development-7","question":"Object permanence develops during which of Piaget’s stages?","options":["Sensorimotor","Pre-operational","Concrete operational","Formal operational"],"answer":0,"explanation":"Object permanence develops in the sensorimotor stage (0–2 years).","difficulty":"hard"},
  {"id":"cdp-child-development-8","question":"According to Piaget, abstract and hypothetical thinking develops in the:","options":["Sensorimotor stage","Pre-operational stage","Concrete operational stage","Formal operational stage"],"answer":3,"explanation":"The formal operational stage (11+ years) brings abstract and hypothetical reasoning.","difficulty":"hard"},
  {"id":"cdp-child-development-9","question":"Kohlberg’s theory deals with:","options":["Cognitive development","Moral development","Psychosocial development","Language development"],"answer":1,"explanation":"Kohlberg proposed three levels and six stages of moral development.","difficulty":"hard"},
  {"id":"cdp-child-development-10","question":"Operant conditioning was proposed by:","options":["Ivan Pavlov","B. F. Skinner","Edward Thorndike","Albert Bandura"],"answer":1,"explanation":"Skinner showed that behaviour is shaped by reinforcement and punishment; Pavlov’s is classical conditioning.","difficulty":"very-hard"},
  {"id":"cdp-child-development-11","question":"“Egocentrism” is a characteristic of which Piagetian stage?","options":["Sensorimotor","Pre-operational","Concrete operational","Formal operational"],"answer":1,"explanation":"Pre-operational children (2–7) find it hard to see things from another person’s point of view.","difficulty":"very-hard"},
  {"id":"cdp-child-development-12","question":"Erik Erikson’s stage of “Industry vs Inferiority” corresponds to the age group:","options":["0–1 years","3–6 years","6–12 years","12–18 years"],"answer":2,"explanation":"Industry vs Inferiority covers the school years, about 6 to 12.","difficulty":"very-hard"},
  {"id":"cdp-child-development-13","question":"According to Piaget, the stage of development from birth to about 2 years is the:","options":["Pre-operational stage","Sensorimotor stage","Concrete operational stage","Formal operational stage"],"answer":1,"explanation":"Infants learn through senses and movement in the sensorimotor stage.","difficulty":"easy","source":"CTET · UPTET"},
  {"id":"cdp-child-development-14","question":"The Right to Education Act, 2009 makes education free and compulsory for children aged:","options":["3–6 years","6–14 years","5–15 years","6–18 years"],"answer":1,"explanation":"The RTE Act covers children from 6 to 14 years.","difficulty":"easy","source":"CTET · SUPER TET"},
  {"id":"cdp-child-development-15","question":"Vygotsky’s “Zone of Proximal Development” refers to the gap between what a child can do:","options":["Alone and with the help of a more capable person","At home and at school","In the morning and the evening","Verbally and in writing"],"answer":0,"explanation":"ZPD is the range of tasks a learner can do with guidance but not yet alone.","difficulty":"moderate","source":"CTET · UPTET"},
  {"id":"cdp-child-development-16","question":"Howard Gardner is known for the theory of:","options":["Moral development","Multiple intelligences","Classical conditioning","Psychosocial development"],"answer":1,"explanation":"Gardner proposed several independent intelligences: linguistic, logical, spatial, musical and more.","difficulty":"moderate","source":"CTET · KVS"},
  {"id":"cdp-child-development-17","question":"Classical conditioning was demonstrated by Pavlov using:","options":["Rats in a box","Dogs and a bell","Pigeons","Children and a doll"],"answer":1,"explanation":"Pavlov paired a bell with food until the bell alone made dogs salivate.","difficulty":"hard","source":"CTET · UPTET"},
  {"id":"cdp-child-development-18","question":"A child who learns to read a word and then reads it again correctly a week later is showing which process of memory?","options":["Encoding","Storage","Retrieval","Forgetting"],"answer":2,"explanation":"Recalling stored information when needed is retrieval.","difficulty":"very-hard","source":"CTET · DSSSB"},
  {"id":"cdp-child-development-19","question":"At Kohlberg’s pre-conventional level, a child judges right and wrong mainly by:","options":["Social approval","Punishment and reward","Universal ethical principles","Law and order"],"answer":1,"explanation":"Pre-conventional morality is about avoiding punishment and getting rewards.","difficulty":"hard"},
  {"id":"cdp-child-development-20","question":"Which of these is an example of formative assessment?","options":["The board exam at the end of the year","Short quizzes with feedback during teaching","An entrance test","The final term exam"],"answer":1,"explanation":"Formative assessment happens during learning and is used to improve it.","difficulty":"hard"},
  {"id":"cdp-child-development-21","question":"Bruner’s three modes of representation are:","options":["Enactive, iconic, symbolic","Sensory, motor, verbal","Concrete, abstract, formal","Visual, auditory, kinaesthetic"],"answer":0,"explanation":"Enactive (action), iconic (images) and symbolic (language).","difficulty":"very-hard"},
  {"id":"cdp-child-development-22","question":"Wolfgang Köhler demonstrated “learning by insight” in experiments with:","options":["Cats","Dogs","Chimpanzees","Pigeons"],"answer":2,"explanation":"His chimpanzee Sultan joined sticks to reach a banana, showing sudden insight.","difficulty":"very-hard"},
  {"id":"cdp-child-development-23","question":"How many of these statements are correct? I. Piaget’s concrete operational stage covers roughly 7 to 11 years. II. Conservation develops in the concrete operational stage. III. Object permanence develops in the sensorimotor stage. IV. Abstract reasoning begins in the pre-operational stage.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. Abstract reasoning belongs to the formal operational stage.","difficulty":"very-hard"},
  {"id":"cdp-child-development-24","question":"How many of these statements are correct? I. The RTE Act, 2009 came into force on 1 April 2010. II. It reserves 25% of entry-level seats in private unaided schools for disadvantaged children. III. It lets schools hold screening tests for admission.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. The Act bans screening procedures and capitation fees.","difficulty":"very-hard"},
  {"id":"cdp-child-development-25","question":"A child knows that a ball of clay rolled into a sausage still has the same amount of clay. According to Piaget, the child has acquired:","options":["Conservation","Object permanence","Egocentrism","Animism"],"answer":0,"explanation":"Conservation develops in the concrete operational stage (about 7 to 11 years).","difficulty":"very-hard"},
  {"id":"cdp-child-development-26","question":"Vygotsky’s Zone of Proximal Development is the gap between:","options":["What a child can do alone and what the child can do with guidance","A child’s mental age and chronological age","What a child knows and what the curriculum expects","A child’s performance at home and at school"],"answer":0,"explanation":"The ZPD is what a learner can do with help from a more knowledgeable other but not yet alone; scaffolding works inside it.","difficulty":"very-hard"},
  {"id":"cdp-child-development-27","question":"How many of these statements are correct? I. Kohlberg’s theory deals with moral development. II. Erikson proposed eight psychosocial stages. III. Piaget proposed five stages of cognitive development.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. Piaget proposed four stages: sensorimotor, pre-operational, concrete operational and formal operational.","difficulty":"very-hard"},
  {"id":"cdp-child-development-28","question":"Which pair of theory and psychologist is NOT correctly matched?","options":["Classical conditioning – Pavlov","Social learning theory – Bandura","Multiple intelligences – Gardner","Trial-and-error learning – Skinner"],"answer":3,"explanation":"Trial-and-error learning, with the laws of effect, exercise and readiness, is Thorndike’s. Skinner gave operant conditioning.","difficulty":"very-hard","source":"CTET · KVS"},
  {"id":"cdp-child-development-29","question":"How many of these statements about Erikson’s theory are correct? I. Trust vs mistrust is the first stage. II. Identity vs role confusion belongs to adolescence. III. The stages end with adolescence. IV. Initiative vs guilt covers roughly 3 to 6 years.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. Erikson’s eight stages run through the whole lifespan, ending with integrity vs despair in old age.","difficulty":"very-hard","source":"CTET · DSSSB"},
  {"id":"cdp-child-development-30","question":"The Right of Children to Free and Compulsory Education Act, 2009 gives effect to which Article of the Constitution?","options":["Article 14","Article 21A","Article 45","Article 51A"],"answer":1,"explanation":"Article 21A, inserted by the 86th Amendment (2002), makes elementary education a fundamental right; Article 45 now deals with early childhood care below six years.","difficulty":"easy","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-31","question":"According to Piaget, the stage of cognitive development from about 2 to 7 years is the:","options":["Sensorimotor stage","Pre-operational stage","Concrete operational stage","Formal operational stage"],"answer":1,"explanation":"The pre-operational stage (2–7 years) is marked by symbolic play, egocentrism and lack of conservation.","difficulty":"easy","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-32","question":"The “law of effect” in learning was proposed by:","options":["Pavlov","Skinner","Thorndike","Bandura"],"answer":2,"explanation":"Thorndike’s law of effect states that responses followed by satisfying consequences are strengthened; Skinner later built operant conditioning on this idea.","difficulty":"easy","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-33","question":"The 5+3+3+4 curricular structure for school education was recommended by:","options":["National Policy on Education, 1986","Right to Education Act, 2009","National Education Policy, 2020","Kothari Commission, 1966"],"answer":2,"explanation":"NEP 2020 replaces the 10+2 pattern with foundational (5 years), preparatory (3), middle (3) and secondary (4) stages covering ages 3 to 18.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-34","question":"The formula IQ = (Mental age ÷ Chronological age) × 100 was given by:","options":["Alfred Binet","William Stern","Lewis Terman","Charles Spearman"],"answer":1,"explanation":"William Stern proposed the intelligence quotient in 1912; Binet devised the mental-age scale and Terman popularised the IQ in the Stanford–Binet test.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-35","question":"According to Vygotsky, the most important tool for cognitive development is:","options":["Maturation","Language","Reinforcement","Physical play"],"answer":1,"explanation":"For Vygotsky, language and social interaction mediate thinking; private speech becomes inner speech that guides problem solving.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-36","question":"A child is generally regarded as “gifted” if the IQ is above:","options":["90","110","130","150"],"answer":2,"explanation":"An IQ of about 130 or more (two standard deviations above the mean of 100) is the usual threshold for giftedness.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-37","question":"An examination held at the end of a term to judge how much students have learnt is an example of:","options":["Formative assessment","Diagnostic assessment","Summative assessment","Placement assessment"],"answer":2,"explanation":"Summative assessment measures learning at the end of a unit or course; formative assessment happens during teaching to improve it.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-38","question":"Dyslexia is a learning disability that mainly affects:","options":["Reading","Arithmetic","Handwriting","Motor coordination"],"answer":0,"explanation":"Dyslexia affects reading and spelling; dyscalculia affects arithmetic, dysgraphia writing and dyspraxia motor coordination.","difficulty":"moderate","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-39","question":"Under NEP 2020, the foundational stage covers children aged:","options":["3 to 6 years","3 to 8 years","6 to 10 years","5 to 8 years"],"answer":1,"explanation":"The foundational stage spans three years of pre-school (ages 3–6) plus classes 1 and 2 (ages 6–8).","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-40","question":"Kohlberg’s “good boy–good girl” orientation, where a child seeks approval of others, belongs to the:","options":["Pre-conventional level","Conventional level","Post-conventional level","Autonomous level"],"answer":1,"explanation":"Stage 3 (interpersonal conformity) is the first stage of the conventional level; stage 4 is law-and-order orientation.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-41","question":"A toddler who has learnt the word “dog” sees a cow for the first time and calls it “dog”. In Piaget’s terms this is an example of:","options":["Accommodation","Assimilation","Equilibration","Conservation"],"answer":1,"explanation":"The child fits new experience into an existing schema (assimilation); creating a new schema for “cow” would be accommodation.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-42","question":"Erikson’s stage of “autonomy vs shame and doubt” corresponds to the age range:","options":["Birth to 1 year","1 to 3 years","3 to 6 years","6 to 12 years"],"answer":1,"explanation":"Toddlers (1–3 years) learn self-control and independence; success gives autonomy, over-restriction gives shame and doubt.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-43","question":"The pupil–teacher ratio prescribed by the RTE Act for classes I to V is:","options":["25:1","30:1","35:1","40:1"],"answer":1,"explanation":"The Schedule to the RTE Act requires 30:1 for classes I–V (two teachers for up to 60 children) and 35:1 for classes VI–VIII.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-44","question":"Dyscalculia refers to a specific learning difficulty in:","options":["Reading","Spelling","Mathematics","Speaking"],"answer":2,"explanation":"Dyscalculia affects number sense and arithmetic; such children struggle with counting, place value and simple calculations.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-45","question":"A student who easily understands the moods and feelings of classmates shows, in Gardner’s theory, a high level of:","options":["Intrapersonal intelligence","Interpersonal intelligence","Naturalistic intelligence","Linguistic intelligence"],"answer":1,"explanation":"Interpersonal intelligence is sensitivity to others’ feelings and motives; intrapersonal intelligence is understanding one’s own emotions.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-46","question":"Bandura’s Bobo doll experiment demonstrated:","options":["Classical conditioning","Insight learning","Observational learning","Trial-and-error learning"],"answer":2,"explanation":"Children who watched an adult hit the doll imitated the aggression, showing that behaviour is learnt by observing models (social learning theory).","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-47","question":"Under the RTE Act, a child above six years who has never been admitted to a school shall be admitted to:","options":["Class I","A class appropriate to his or her age","A bridge course for one year first","A pre-primary class"],"answer":1,"explanation":"Section 4 provides age-appropriate admission with special training to help the child catch up with peers.","difficulty":"hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-48","question":"How many of these statements about Piaget’s theory are correct? I. The formal operational stage begins at about 11 years. II. Reversibility of thought is achieved in the concrete operational stage. III. Animism is a feature of the pre-operational stage. IV. Piaget held that learning precedes development.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: Piaget held that development precedes and limits learning; it is Vygotsky who argued that learning can lead development.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-49","question":"Assertion (A): Vygotsky stressed scaffolding by a more knowledgeable other. Reason (R): For Vygotsky, cognitive development is a socially mediated process.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Because higher mental functions develop through interaction with capable others, support within the zone of proximal development (scaffolding) is central; R is the reason for A.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-50","question":"Match Kohlberg’s stages with their orientations: 1. Stage 1 2. Stage 2 3. Stage 4 4. Stage 6; a. Universal ethical principles b. Law and order c. Punishment and obedience d. Instrumental exchange (“what’s in it for me”)","options":["1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-b, 4-a","1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-a, 4-b"],"answer":0,"explanation":"Stage 1 punishment–obedience, stage 2 instrumental exchange, stage 3 good boy–good girl, stage 4 law and order, stage 5 social contract, stage 6 universal ethical principles.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-51","question":"Which of the following is NOT a principle of development?","options":["Development proceeds from head to toe (cephalocaudal)","Development proceeds from the centre of the body outward (proximodistal)","Development proceeds from specific to general","Development is a continuous process"],"answer":2,"explanation":"Development moves from general to specific: a baby waves its whole arm before it can grasp with its fingers.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-52","question":"How many of these statements about the RTE Act, 2009 are correct? I. It covers children aged 6 to 14 years. II. Section 12(1)(c) requires private unaided schools to admit at least 25% children from weaker sections in the entry class. III. No board examination may be held until the completion of elementary education. IV. Mild physical punishment is permitted as a last resort.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct (Section 30 bars board exams). IV is wrong: Section 17 prohibits all physical punishment and mental harassment.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-53","question":"How many of these statements about NEP 2020 are correct? I. It replaces the 10+2 structure with 5+3+3+4. II. It aims at a 100% Gross Enrolment Ratio in school education by 2030. III. It makes the mother tongue compulsory as the medium of instruction up to class 8. IV. It was approved by the Union Cabinet on 29 July 2020.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. III is wrong: NEP 2020 says the home language or mother tongue should be the medium “wherever possible” at least till class 5, preferably till class 8; it is a recommendation, not a compulsion.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-54","question":"In Maslow’s hierarchy, which need comes immediately above safety needs?","options":["Esteem needs","Self-actualisation","Belongingness and love needs","Physiological needs"],"answer":2,"explanation":"The order from the base is physiological → safety → belongingness and love → esteem → self-actualisation.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-55","question":"Assertion (A): A teacher should use formative assessment regularly during a unit. Reason (R): Formative assessment gives feedback that lets the teacher modify teaching while learning is still in progress.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Formative assessment is “assessment for learning”; its purpose is timely feedback, which is exactly why it should be continuous.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-56","question":"Match the psychologist with the concept: 1. Pavlov 2. Chomsky 3. Binet 4. Spearman; a. g-factor of intelligence b. Language acquisition device c. First intelligence test d. Classical conditioning","options":["1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-b, 4-a","1-b, 2-d, 3-c, 4-a","1-d, 2-b, 3-a, 4-c"],"answer":0,"explanation":"Pavlov → classical conditioning, Chomsky → innate language acquisition device, Binet → first practical intelligence test (1905), Spearman → two-factor (g and s) theory.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-57","question":"How many of these statements about theories of intelligence are correct? I. Spearman proposed the two-factor theory. II. Thurstone proposed seven primary mental abilities. III. The Binet–Simon scale was first published in 1905. IV. Sternberg’s triarchic theory includes analytical, creative and practical intelligence.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct; the common confusion is attributing multiple intelligences (Gardner) to Thurstone or the g-factor to Binet.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-58","question":"A four-year-old says her doll is “sad” because it fell down. According to Piaget, this illustrates:","options":["Conservation","Animism","Reversibility","Decentration"],"answer":1,"explanation":"Animism, attributing life and feelings to inanimate objects, is typical of the pre-operational stage; conservation and reversibility come later.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id":"cdp-child-development-59","question":"A student refuses to copy in an examination, saying “rules must be obeyed, otherwise there will be chaos in school”. In Kohlberg’s scheme the student is at:","options":["Stage 1, punishment and obedience","Stage 3, interpersonal conformity","Stage 4, law and order","Stage 5, social contract"],"answer":2,"explanation":"Reasoning that rules must be upheld to maintain social order is the law-and-order orientation (stage 4, conventional level); stage 1 would cite fear of punishment.","difficulty":"very-hard","source":"CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-60", "question": "Inclusive education means:", "options": ["Separate schools for children with disabilities", "Educating all children, including those with disabilities, together in regular classrooms", "Admitting only high-achieving students", "Teaching only through the mother tongue"], "answer": 1, "explanation": "Inclusive education places every child, whatever their ability, background or disability, in the same classroom and adapts teaching to meet their needs.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-61", "question": "The idea of “learning by doing” is most closely associated with:", "options": ["B. F. Skinner", "Ivan Pavlov", "John Dewey", "Sigmund Freud"], "answer": 2, "explanation": "John Dewey, the pragmatist philosopher, held that children learn best through activity and real experience rather than passive listening.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-62", "question": "Kohlberg’s theory of moral development has:", "options": ["Three stages in one level", "Six stages grouped into three levels", "Eight stages in four levels", "Four stages in two levels"], "answer": 1, "explanation": "Kohlberg described pre-conventional, conventional and post-conventional levels, each with two stages, making six stages in all.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-63", "question": "Which of these is an example of intrinsic motivation?", "options": ["A student studies to get a prize", "A student reads storybooks because she enjoys reading", "A student works hard to avoid punishment", "A student studies to please his parents"], "answer": 1, "explanation": "Intrinsic motivation comes from interest and enjoyment of the activity itself. Prizes, punishment and approval of others are external (extrinsic) motivators.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-64", "question": "ADHD, a condition that affects a child’s attention and self-control in class, stands for:", "options": ["Attention Deficit Hyperactivity Disorder", "Auditory Development Hearing Disorder", "Acquired Developmental Handicap Disorder", "Attention Delay and Hearing Difficulty"], "answer": 0, "explanation": "Children with Attention Deficit Hyperactivity Disorder find it hard to sustain attention and may be impulsive or overactive; short tasks and structured routines help them.", "difficulty": "moderate", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-65", "question": "Continuous and comprehensive evaluation (CCE) of a child’s understanding is provided for in which law?", "options": ["The Right to Education Act, 2009", "The Rights of Persons with Disabilities Act, 2016", "The Juvenile Justice Act, 2015", "The National Commission for Protection of Child Rights Act, 2005"], "answer": 0, "explanation": "Section 29(2) of the RTE Act requires the curriculum and evaluation procedure to include comprehensive and continuous evaluation of the child’s understanding and ability to apply knowledge.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-66", "question": "According to Freud, the “id” operates on the:", "options": ["Reality principle", "Morality principle", "Pleasure principle", "Social principle"], "answer": 2, "explanation": "The id seeks immediate gratification (pleasure principle), the ego follows the reality principle, and the superego represents moral standards.", "difficulty": "moderate", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-67", "question": "In Piaget’s theory, a “schema” is:", "options": ["A punishment used to stop bad behaviour", "An organised pattern of thought or action used to understand the world", "A formal test of intelligence", "The gap between what a child can do alone and with help"], "answer": 1, "explanation": "Schemas are mental frameworks that are built and changed through assimilation and accommodation. The gap described in the last option is Vygotsky’s ZPD.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-68", "question": "Which intelligence did Howard Gardner add in 1995 as the eighth in his theory of multiple intelligences?", "options": ["Existential", "Naturalistic", "Emotional", "Spiritual"], "answer": 1, "explanation": "Gardner added naturalistic intelligence (recognising and classifying plants, animals and nature) in 1995. Existential intelligence has only been suggested as a possible ninth.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-69", "question": "Which of these is NOT one of Thorndike’s primary laws of learning?", "options": ["Law of readiness", "Law of exercise", "Law of effect", "Law of insight"], "answer": 3, "explanation": "Thorndike’s three primary laws are readiness, exercise and effect. Insight learning comes from Köhler and the Gestalt school.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-70", "question": "A teacher asks, “In how many ways can we use a brick?” This question mainly encourages:", "options": ["Convergent thinking", "Divergent thinking", "Rote memory", "Concrete operational thinking"], "answer": 1, "explanation": "Open-ended questions with many possible answers promote divergent (creative) thinking. Convergent thinking aims at one correct answer.", "difficulty": "hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-71", "question": "According to Vygotsky, a child talking aloud to herself while solving a puzzle (private speech):", "options": ["Shows that she is egocentric and immature", "Helps her guide and regulate her own thinking", "Is a sign of a language disorder", "Should be stopped by the teacher at once"], "answer": 1, "explanation": "Vygotsky saw private speech as a tool of self-regulation that later becomes inner speech. Piaget, by contrast, called it egocentric speech.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-72", "question": "Which of the following is a projective test of personality?", "options": ["16PF questionnaire", "Rorschach inkblot test", "Stanford–Binet test", "Raven’s Progressive Matrices"], "answer": 1, "explanation": "In the Rorschach test the subject interprets ambiguous inkblots, projecting inner feelings. 16PF is a self-report inventory, while Stanford–Binet and Raven’s are intelligence tests.", "difficulty": "hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-73", "question": "A test given to find the specific areas in which a student has learning difficulties is a:", "options": ["Diagnostic test", "Achievement test", "Aptitude test", "Placement test"], "answer": 0, "explanation": "A diagnostic test pinpoints the exact weaknesses so that remedial teaching can follow. An achievement test measures how much has been learnt.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-74", "question": "Arrange these levels of Bloom’s revised taxonomy from the lowest to the highest: 1. Applying 2. Remembering 3. Creating 4. Analysing", "options": ["2, 1, 4, 3", "2, 4, 1, 3", "1, 2, 4, 3", "2, 1, 3, 4"], "answer": 0, "explanation": "The revised taxonomy (Anderson and Krathwohl, 2001) runs Remembering → Understanding → Applying → Analysing → Evaluating → Creating, with Creating at the top.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-75", "question": "Assertion (A): Constructivist teaching discourages rote memorisation of facts. Reason (R): Constructivism holds that learners actively build knowledge by linking new experiences to what they already know.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Because knowledge is constructed, not received, constructivists prefer activities, discussion and exploration over memorising. R explains A.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-76", "question": "Assertion (A): Boys and girls should be given different curricula because gender decides intellectual ability. Reason (R): Gender roles are largely shaped by society through socialisation.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "A is false: intellectual ability does not depend on gender, and separate curricula reinforce stereotypes. R is true: gender is a social construct learnt through family, school and media.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-77", "question": "Match the psychologist with the idea: 1. Albert Bandura 2. Jerome Bruner 3. David Ausubel 4. Wolfgang Köhler; a. Insight learning b. Meaningful verbal learning and advance organisers c. Discovery learning d. Social (observational) learning", "options": ["1-d, 2-b, 3-c, 4-a", "1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-a, 4-b", "1-d, 2-c, 3-b, 4-a"], "answer": 3, "explanation": "Bandura proposed social learning, Bruner discovery learning, Ausubel meaningful reception learning with advance organisers, and Köhler insight learning.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-78", "question": "Child A is 8 years old with a mental age of 10 years; child B is 10 years old with a mental age of 8 years. What is the difference between their IQs?", "options": ["20", "45", "25", "2"], "answer": 1, "explanation": "IQ = (MA ÷ CA) × 100. A: 10/8 × 100 = 125. B: 8/10 × 100 = 80. Difference = 125 − 80 = 45.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-79", "question": "Which of the following is NOT a feature of a child-centred classroom?", "options": ["Children learn through activities and discussion", "The teacher acts as a facilitator", "The textbook is treated as the only source of knowledge and the teacher as the sole authority", "Children’s experiences are linked to what is taught"], "answer": 2, "explanation": "Child-centred pedagogy uses many sources of learning and treats the teacher as a facilitator; seeing the textbook and teacher as the sole authority is the traditional, teacher-centred approach.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-80", "question": "How many of these statements about the Rights of Persons with Disabilities Act, 2016 are correct? I. It recognises 21 types of disabilities. II. It replaced the Persons with Disabilities Act, 1995. III. It gives every child with benchmark disability aged 6 to 18 years the right to free education. IV. Specific learning disabilities are not included among the specified disabilities.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: specific learning disabilities (such as dyslexia) are among the 21 specified disabilities, up from seven in the 1995 Act.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-81", "question": "How many of these statements are correct? I. Piaget saw the child as a “little scientist” who constructs knowledge. II. Vygotsky argued that learning leads development. III. Piaget held that language drives thought. IV. Vygotsky proposed four universal, fixed stages of cognitive development.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and II are correct. Piaget held that thought comes before language, and the four universal stages are Piaget’s idea; Vygotsky stressed culture and social interaction instead of fixed stages.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-82", "question": "A teacher excuses students from an extra written task whenever they listen attentively in class, and attentive listening increases. This is an example of:", "options": ["Positive reinforcement", "Negative reinforcement", "Punishment", "Extinction"], "answer": 1, "explanation": "Removing something unpleasant (the extra task) to strengthen a behaviour is negative reinforcement. Punishment weakens behaviour, so it is the common wrong answer.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-83", "question": "How many of these are examples of assessment for learning? I. Oral questions during a lesson followed by feedback II. Peer assessment of first drafts III. A year-end board examination IV. A portfolio reviewed with feedback during the term", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV give feedback while learning is going on, so they are assessment for learning (formative). A year-end board exam is assessment of learning (summative).", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-84", "question": "Arrange in chronological order: 1. National Curriculum Framework 2005 2. Right to Education Act 3. Kothari Commission report 4. National Education Policy 2020", "options": ["3, 2, 1, 4", "1, 3, 2, 4", "3, 1, 2, 4", "3, 1, 4, 2"], "answer": 2, "explanation": "Kothari Commission report 1966 → NCF 2005 → RTE Act 2009 → NEP 2020.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-85", "question": "Who described adolescence as a period of ‘storm and stress’?", "options": ["G. Stanley Hall", "John Dewey", "Sigmund Freud", "Jean Piaget"], "answer": 0, "explanation": "G. Stanley Hall, in his 1904 work on adolescence, called it a time of ‘storm and stress’ marked by emotional ups and downs. Later researchers found that not every adolescent goes through such turmoil.", "difficulty": "easy", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-86", "question": "The ‘kindergarten’ (children’s garden) system of early education was started by:", "options": ["John Locke", "Rabindranath Tagore", "Friedrich Froebel", "Maria Montessori"], "answer": 2, "explanation": "Friedrich Froebel opened the first kindergarten in Germany in 1837, stressing play, songs and ‘gifts’ (educational toys). Montessori developed her own method later, around 1907.", "difficulty": "easy", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-87", "question": "‘Emile’, the book that urged education according to the child’s nature, was written by:", "options": ["Jean-Jacques Rousseau", "John Dewey", "Johann Pestalozzi", "Plato"], "answer": 0, "explanation": "Rousseau’s ‘Emile’ (1762) argued that children should learn through nature and experience at their own pace, an early root of child-centred education.", "difficulty": "easy", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-88", "question": "Development of control proceeding from the head towards the feet, so that a baby controls its head before its legs, is called the:", "options": ["Cephalocaudal principle", "Principle of individual differences", "Principle of integration", "Proximodistal principle"], "answer": 0, "explanation": "Cephalocaudal means ‘head to tail’. The proximodistal principle describes development from the centre of the body outward, for example arm control before finger control.", "difficulty": "moderate", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-89", "question": "The Montessori method of education places the greatest emphasis on:", "options": ["Self-directed learning with specially designed sensory materials", "Rote learning under strict teacher control", "Competitive examinations from an early age", "Learning only through stories told by the teacher"], "answer": 0, "explanation": "Montessori classrooms give children self-correcting materials that train the senses, so they learn by themselves (auto-education) while the teacher observes and guides.", "difficulty": "moderate", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-90", "question": "The theory that an infant’s early emotional bond with a caregiver shapes later relationships is the attachment theory of:", "options": ["John Bowlby", "Lawrence Kohlberg", "Edward Thorndike", "B. F. Skinner"], "answer": 0, "explanation": "John Bowlby argued that a secure attachment to a responsive caregiver gives the child a safe base from which to explore. Mary Ainsworth later studied attachment types with the ‘strange situation’ test.", "difficulty": "moderate", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-91", "question": "Parents who are warm and responsive but also set clear rules and explain them follow which parenting style, according to Diana Baumrind?", "options": ["Authoritative", "Authoritarian", "Permissive", "Neglectful"], "answer": 0, "explanation": "Authoritative parenting combines high warmth with high control and is linked with confident, self-reliant children. Authoritarian parents are strict but cold, and permissive parents are warm but set few limits.", "difficulty": "moderate", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-92", "question": "A ‘spiral curriculum’, in which topics are revisited at increasing levels of depth, was proposed by:", "options": ["Jean Piaget", "Jerome Bruner", "Abraham Maslow", "Ivan Pavlov"], "answer": 1, "explanation": "Bruner held that any subject can be taught in some honest form to any child, and then revisited in more complex forms as the child grows.", "difficulty": "moderate", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-93", "question": "The ‘forgetting curve’, showing that most forgetting happens soon after learning, was given by:", "options": ["Wolfgang Köhler", "Hermann Ebbinghaus", "Albert Bandura", "Howard Gardner"], "answer": 1, "explanation": "Ebbinghaus tested his own memory of nonsense syllables and found a steep early drop in retention that later levels off. This is why regular revision soon after learning helps.", "difficulty": "moderate", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-94", "question": "A child who calls every four-legged animal ‘dog’ learns that cows are different and forms a new category for them. In Piaget’s terms, the child has shown:", "options": ["Conservation", "Object permanence", "Assimilation", "Accommodation"], "answer": 3, "explanation": "Accommodation is changing an existing schema or making a new one when new experience does not fit. Calling the cow ‘dog’ in the first place would have been assimilation.", "difficulty": "hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-95", "question": "Carol Gilligan criticised Kohlberg’s theory of moral development mainly because she felt it:", "options": ["Had too few stages", "Was based largely on male subjects and overlooked an ‘ethic of care’", "Ignored the role of rewards", "Was meant only for adults"], "answer": 1, "explanation": "Gilligan argued that Kohlberg’s justice-based stages, drawn mostly from boys, undervalued moral reasoning based on care and relationships, which she found more often in women.", "difficulty": "hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-96", "question": "J. P. Guilford’s ‘Structure of Intellect’ model classifies intellectual abilities along which three dimensions?", "options": ["Operations, contents and products", "Fluid, crystallised and general", "Analytical, creative and practical", "Verbal, numerical and spatial"], "answer": 0, "explanation": "Guilford crossed operations (such as cognition and divergent production), contents and products to produce many distinct abilities. Analytical, creative and practical belong to Sternberg, and fluid–crystallised to Cattell.", "difficulty": "hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-97", "question": "The idea of ‘emotional intelligence’ was popularised by whose 1995 book?", "options": ["Alfred Binet", "Robert Sternberg", "Howard Gardner", "Daniel Goleman"], "answer": 3, "explanation": "Daniel Goleman’s ‘Emotional Intelligence’ (1995) spread the concept, first proposed by Salovey and Mayer, of recognising and managing one’s own and others’ emotions.", "difficulty": "hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-98", "question": "A child who has learnt to ride a bicycle finds it easier to learn to ride a scooter. This is an example of:", "options": ["Retroactive inhibition", "Zero transfer", "Negative transfer", "Positive transfer"], "answer": 3, "explanation": "Positive transfer occurs when earlier learning helps new learning because the skills share elements such as balance. Negative transfer is when earlier learning gets in the way.", "difficulty": "hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-99", "question": "The NIPUN Bharat Mission, launched in July 2021, aims to ensure that every child achieves:", "options": ["Proficiency in English by Class 5", "Digital literacy by Class 8", "Vocational skills by Class 10", "Foundational literacy and numeracy by the end of Class 3"], "answer": 3, "explanation": "NIPUN Bharat (National Initiative for Proficiency in Reading with Understanding and Numeracy) targets foundational literacy and numeracy by the end of Grade 3, with 2026–27 as the target year.", "difficulty": "hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-100", "question": "‘Action research’ was introduced into education to help teachers solve their own classroom problems by:", "options": ["B. F. Skinner", "Jean Piaget", "Kurt Lewin, applied to schools by Stephen M. Corey", "Lev Vygotsky"], "answer": 2, "explanation": "Kurt Lewin coined the term, and Stephen M. Corey popularised action research in education in the 1950s as a way for teachers to study and improve their own practice.", "difficulty": "hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-101", "question": "Paulo Freire criticised the ‘banking concept’ of education, in which:", "options": ["The teacher deposits information into passive students", "Students save marks for later examinations", "Students are taught how to manage money", "Schools are run like banks for profit"], "answer": 0, "explanation": "In ‘Pedagogy of the Oppressed’ Freire argued against treating learners as empty accounts to be filled, and called for dialogue and critical thinking instead.", "difficulty": "hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-102", "question": "A student who learnt French last year keeps mixing up French words while learning Spanish this year. This is an example of:", "options": ["Positive transfer", "Proactive interference", "Decay", "Retroactive interference"], "answer": 1, "explanation": "In proactive interference old learning disrupts the recall of new learning. If the new Spanish words made the student forget French, that would be retroactive interference.", "difficulty": "hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-103", "question": "How many of these statements about the principles of development are correct? I. Development is a continuous process. II. Development proceeds from the centre of the body outward. III. All children develop at the same rate. IV. Development results from the interaction of heredity and environment.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct; II is the proximodistal principle. III is wrong: development follows a similar sequence in all children, but its rate differs from child to child.", "difficulty": "very-hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-104", "question": "Match the learning difficulty with the area it mainly affects: 1. Dyslexia 2. Dysgraphia 3. Dyspraxia 4. Dysphasia; a. Language and speech b. Motor coordination c. Writing d. Reading", "options": ["1-d, 2-b, 3-c, 4-a", "1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-b, 4-a", "1-d, 2-c, 3-a, 4-b"], "answer": 2, "explanation": "Dyslexia affects reading, dysgraphia writing, dyspraxia the planning and coordination of movement, and dysphasia the use and understanding of spoken language.", "difficulty": "very-hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-105", "question": "Assertion (A): Teachers should avoid labelling children as ‘slow learners’ or ‘failures’. Reason (R): Labels can lower a child’s self-concept and teachers’ expectations, which can then become a self-fulfilling prophecy.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Studies of the Pygmalion effect show that children tend to perform as teachers expect, so a negative label can push achievement down. That is why R explains A.", "difficulty": "very-hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-106", "question": "A student argues: ‘Laws are agreements made by people for the common good; if a law violates basic rights, it should be changed through democratic means.’ In Kohlberg’s scheme this reasoning belongs to:", "options": ["Stage 5, social contract orientation", "Stage 2, instrumental exchange", "Stage 3, good boy–good girl orientation", "Stage 4, law and order orientation"], "answer": 0, "explanation": "Seeing laws as changeable social contracts that should protect rights is Stage 5 (post-conventional). Stage 4 treats laws as fixed rules to be obeyed to keep order.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-107", "question": "How many of these statements are correct? I. PARAKH was set up as a national assessment centre under the NCERT. II. The National Curriculum Framework for the Foundational Stage (2022) covers children aged 6 to 14. III. Vidya Pravesh is a three-month play-based school-preparation module for children entering Grade 1. IV. The National Curriculum Framework for School Education (2023) was drafted by a committee headed by Dr K. Kasturirangan.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, III and IV are correct. II is wrong: the foundational stage covers ages 3 to 8 (three years of pre-school plus Grades 1 and 2).", "difficulty": "very-hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-108", "question": "Arrange in chronological order: 1. Bandura’s Bobo doll experiments 2. Gardner proposes multiple intelligences 3. Binet–Simon intelligence scale 4. Skinner publishes ‘The Behavior of Organisms’", "options": ["3, 4, 1, 2", "3, 4, 2, 1", "3, 1, 4, 2", "4, 3, 1, 2"], "answer": 0, "explanation": "The Binet–Simon scale came in 1905, Skinner’s book on operant conditioning in 1938, the Bobo doll studies in 1961 and Gardner’s ‘Frames of Mind’ in 1983.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-109", "question": "A student who fails a test says, ‘I was just unlucky today.’ According to Weiner’s attribution theory, the student has attributed the failure to a cause that is:", "options": ["External, stable and controllable", "External, unstable and uncontrollable", "Internal, stable and uncontrollable", "Internal, unstable and controllable"], "answer": 1, "explanation": "Luck lies outside the person, changes from day to day and cannot be controlled. Lack of effort would be internal, unstable and controllable, and low ability internal, stable and uncontrollable.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-110", "question": "Match the defence mechanism with its example: 1. Rationalisation 2. Projection 3. Displacement 4. Regression; a. An older child starts sucking his thumb after a sibling is born b. A child scolded by the teacher kicks his little brother at home c. A dishonest pupil accuses classmates of cheating d. A boy who is not chosen for the team says he never wanted to play anyway", "options": ["1-d, 2-c, 3-a, 4-b", "1-d, 2-b, 3-c, 4-a", "1-c, 2-d, 3-b, 4-a", "1-d, 2-c, 3-b, 4-a"], "answer": 3, "explanation": "Rationalisation gives a convenient excuse (sour grapes), projection puts one’s own faults on others, displacement vents feelings on a safer target, and regression is a return to earlier, childish behaviour.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-111", "question": "Which of the following is NOT usually a characteristic of a creative child?", "options": ["Preference for a single, fixed correct answer", "Curiosity and asking unusual questions", "Tolerance for ambiguity", "Divergent thinking"], "answer": 0, "explanation": "Creative children produce many original ideas and are comfortable with open-ended problems. Looking for one fixed answer is convergent thinking, which tests of creativity do not reward.", "difficulty": "very-hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-112", "question": "Assertion (A): Gifted children do not need any special educational provision because they can learn on their own. Reason (R): Gifted children have exceptional abilities that need enrichment or acceleration to develop fully.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "A is false and R is true. Without challenge, gifted children may become bored, underachieve or develop behaviour problems, so they need enrichment, acceleration or ability-appropriate tasks.", "difficulty": "very-hard", "source": "CTET · UPTET · State TETs"},
  {"id": "cdp-child-development-113", "question": "How many of these statements about intelligence tests are correct? I. The Stanford–Binet test is an individual test. II. The WISC was developed by David Wechsler. III. Raven’s Progressive Matrices is a verbal test. IV. Bhatia’s Battery is a verbal test of intelligence.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only I and II are correct. Raven’s Progressive Matrices is a non-verbal, culture-reducing test of abstract reasoning, and C. M. Bhatia’s Battery is a set of performance tests designed for Indian children.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-114", "question": "Arrange Bronfenbrenner’s environmental systems from the innermost to the outermost around the child: 1. Exosystem 2. Microsystem 3. Macrosystem 4. Mesosystem", "options": ["2, 1, 4, 3", "2, 4, 3, 1", "2, 4, 1, 3", "4, 2, 1, 3"], "answer": 2, "explanation": "The microsystem (family, school) is closest; the mesosystem links microsystems (home–school); the exosystem affects the child indirectly (a parent’s workplace); the macrosystem is the wider culture. The chronosystem adds change over time.", "difficulty": "very-hard", "source": "CTET · KVS · State TETs"},
  {"id": "cdp-child-development-115", "question": "Which of the following is NOT usually counted as a domain of child development?", "options": ["Physical", "Cognitive", "Socio-emotional", "Financial"], "answer": 3, "explanation": "Child development is usually studied in physical, cognitive (including language) and socio-emotional domains, which interact with one another.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-116", "question": "The “Heinz dilemma”, about a man who steals a drug to save his dying wife, was used to study moral reasoning by:", "options": ["Jean Piaget", "Lawrence Kohlberg", "Erik Erikson", "Albert Bandura"], "answer": 1, "explanation": "Kohlberg classified children's reasons for their answers, not the answers themselves, into six stages of moral reasoning.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-117", "question": "A baby first controls the movements of the shoulders and arms, and only later the fingers. This illustrates the:", "options": ["Cephalocaudal principle", "Principle of individual differences", "Proximodistal principle", "Principle of interaction"], "answer": 2, "explanation": "Proximodistal development proceeds from the centre of the body outwards. Cephalocaudal development proceeds from head to foot.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-118", "question": "In Erikson's theory, the stage of “initiative vs guilt” corresponds roughly to the age of:", "options": ["Birth to 1 year", "3 to 6 years", "6 to 12 years", "12 to 18 years"], "answer": 1, "explanation": "Pre-school children who are encouraged to plan and try things develop initiative; harsh criticism breeds guilt. Industry vs inferiority follows in the school years.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-119", "question": "A collection of a child's work gathered over a term to show progress and reflection is called a:", "options": ["Portfolio", "Rubric", "Anecdotal record", "Achievement test"], "answer": 0, "explanation": "A portfolio shows growth over time and often includes the child's own reflections. A rubric is a scoring guide; an anecdotal record notes a single observed incident.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-120", "question": "A five-year-old says a tall, thin glass holds more juice than a short, wide one with the same amount, looking only at the height. According to Piaget, this shows:", "options": ["Animism", "Centration", "Object permanence", "Hypothetical reasoning"], "answer": 1, "explanation": "Centration is focusing on one striking feature and ignoring others, typical of the pre-operational stage; it is why such children fail conservation tasks.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-121", "question": "The ability to arrange sticks in order of length (seriation) generally develops in which Piagetian stage?", "options": ["Sensorimotor", "Pre-operational", "Formal operational", "Concrete operational"], "answer": 3, "explanation": "Seriation, along with conservation, reversibility and class inclusion, is mastered in the concrete operational stage (about 7 to 11 years).", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-122", "question": "Raymond Cattell divided general intelligence into:", "options": ["Fluid and crystallised intelligence", "Verbal and performance intelligence", "Analytical, creative and practical intelligence", "Primary mental abilities"], "answer": 0, "explanation": "Fluid intelligence is the ability to reason with new problems; crystallised intelligence is accumulated knowledge. Sternberg proposed the triarchic model and Thurstone the primary mental abilities.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-123", "question": "Robert Sternberg's triarchic theory describes intelligence as having which three aspects?", "options": ["Verbal, numerical and spatial", "Fluid, crystallised and emotional", "Analytical, creative and practical", "Linguistic, logical and musical"], "answer": 2, "explanation": "Sternberg's theory includes componential (analytical), experiential (creative) and contextual (practical) intelligence.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-124", "question": "Rats that explored a maze without reward and then quickly found the food once it was introduced showed that they had learnt the layout. Who described this “latent learning”?", "options": ["Edward Tolman", "Ivan Pavlov", "B. F. Skinner", "Edward Thorndike"], "answer": 0, "explanation": "Tolman argued the rats had formed a “cognitive map” that was not shown until there was a reason to use it, challenging strict behaviourism.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-125", "question": "George Miller's classic finding about short-term memory is that it can hold about:", "options": ["Two or three items", "Seven, plus or minus two, items", "Twenty items", "An unlimited number of items for a few seconds"], "answer": 1, "explanation": "Miller (1956) put the span at about 7 ± 2 chunks; grouping information into chunks helps learners hold more.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-126", "question": "To build a “growth mindset” as described by Carol Dweck, a teacher should mainly praise children for:", "options": ["Being naturally clever", "Getting answers right quickly", "Effort, strategies and persistence", "Finishing before others"], "answer": 2, "explanation": "Praising effort and strategy teaches that ability can grow; praising only “cleverness” can make children avoid challenges for fear of failing.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-127", "question": "After the RTE (Amendment) Act, 2019, which is true of examinations in Classes 5 and 8?", "options": ["Detention is completely prohibited in every class", "Board examinations are compulsory in Class 5", "Children failing the exam get a re-examination within two months and may be held back if they fail again, if the State so decides", "Only private schools may hold back students"], "answer": 2, "explanation": "The amendment to Section 16 lets the appropriate government hold regular exams in Classes 5 and 8, with a re-exam within two months, before a child can be held back.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-128", "question": "Consider the following statements about Bloom's revised taxonomy (2001): 1. It names the levels with verbs, such as remembering and understanding, instead of nouns. 2. It places creating above evaluating at the top. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Anderson and Krathwohl's revision renamed the levels and replaced “synthesis” with “creating” as the highest level.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-129", "question": "Arrange the levels of the affective domain (Krathwohl) from the lowest to the highest: 1. Valuing 2. Receiving 3. Characterisation 4. Responding 5. Organisation", "options": ["2, 4, 1, 3, 5", "2, 1, 4, 5, 3", "4, 2, 1, 5, 3", "2, 4, 1, 5, 3"], "answer": 3, "explanation": "The order is receiving, responding, valuing, organisation and characterisation by a value, as values become part of the learner's character.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-130", "question": "Match the section of the RTE Act, 2009 with its subject: A. Section 13 B. Section 17 C. Section 21 D. Section 29 — 1. School Management Committee 2. Ban on capitation fee and screening for admission 3. Curriculum and evaluation procedure 4. Ban on physical punishment and mental harassment", "options": ["A-2, B-4, C-1, D-3", "A-4, B-2, C-1, D-3", "A-2, B-4, C-3, D-1", "A-2, B-1, C-4, D-3"], "answer": 0, "explanation": "Section 13 bars capitation fees and screening, 17 bans corporal punishment, 21 requires School Management Committees, and 29 lays down curriculum principles, including continuous and comprehensive evaluation.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-131", "question": "Assertion (A): Samagra Shiksha treats school education as a continuum from pre-school to Class XII. Reason (R): Launched in 2018, it subsumed the Sarva Shiksha Abhiyan, the Rashtriya Madhyamik Shiksha Abhiyan and the Teacher Education scheme.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A: merging the elementary, secondary and teacher-education schemes created one integrated programme for all stages of school.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-132", "question": "How many of these abilities are typically achieved in Piaget's concrete operational stage? I. Reversibility II. Conservation III. Hypothetico-deductive reasoning IV. Class inclusion", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV belong to the concrete operational stage. Hypothetico-deductive reasoning about abstract possibilities develops in the formal operational stage.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-133", "question": "Consider the following statements about Vygotsky's ideas: 1. The “more knowledgeable other” can be a peer, not only an adult. 2. Scaffolding should be gradually withdrawn as the child becomes competent. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. This is why peer tutoring and group work are useful, and why support is faded so the learner can work independently.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-child-development-134", "question": "Assertion (A): Shown seven roses and three lilies and asked, “Are there more roses or more flowers?”, a pre-operational child often says “more roses”. Reason (R): Pre-operational children have not yet mastered class inclusion.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A: the child compares the two sub-classes instead of the sub-class with the whole class, an ability that comes in the concrete operational stage.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id":"cdp-child-development-135","question":"A six-year-old agrees that two rows of seven coins are equal when they are lined up. When one row is spread out, she says it has more. When the teacher pushes it back, she says they are equal again, but on spreading it once more she repeats her claim. Which feature of pre-operational thought most directly stops her from mentally ‘undoing’ the change?","options":["Animism","Irreversibility","Lack of object permanence","Transductive reasoning"],"answer":1,"explanation":"She cannot run the transformation backwards in her head, so each new layout is judged afresh; this is irreversibility. Centration on length adds to the error, but the inability to undo the change is the core limitation asked about.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-136","question":"A teacher helps a Class 2 child assemble a 30-piece jigsaw. Which of her actions goes AGAINST the principle of scaffolding?","options":["Showing how to start with the edge pieces and then letting the child continue","Asking, ‘Which pieces have a straight side?’ to focus the child’s attention","Giving the same step-by-step hints for every piece even after the child has begun fitting pieces on her own","Grouping the pieces by colour so that the task is broken into smaller parts"],"answer":2,"explanation":"Scaffolding is temporary and contingent: support should fade as competence grows. Continuing full hints after the child shows independence removes the challenge that drives development.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-137","question":"Two eight-year-olds both solve tasks up to an eight-year level on their own. With hints and leading questions, Arjun solves tasks up to a twelve-year level, while Bunty reaches only a nine-year level. From Vygotsky’s viewpoint, the most valid conclusion is:","options":["Their actual development is the same, but Arjun has a wider zone of proximal development and can benefit from more advanced instruction","Both children are at the same level of development, so they should be taught in exactly the same way","Arjun is more intelligent, because his independent score is higher than Bunty’s","Bunty has reached the upper limit of his development and cannot learn further"],"answer":0,"explanation":"Vygotsky argued that what a child can do with help reveals maturing functions; equal independent scores can hide very different ZPDs, which matter for instruction. Their independent scores are equal, so the third option is factually wrong.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-138","question":"Asked why he shares his tiffin with Kabir, a nine-year-old says, ‘Kabir gave me half his sandwich yesterday, and if I share today he’ll share tomorrow too.’ This reasoning best fits Kohlberg’s:","options":["Stage 3: good boy–good girl orientation","Stage 1: punishment and obedience orientation","Stage 4: law and order orientation","Stage 2: instrumental exchange (‘you scratch my back, I’ll scratch yours’) orientation"],"answer":3,"explanation":"The act is justified by a fair deal that serves his own interest, the hallmark of Stage 2. Stage 3 would appeal to being seen as a good, caring friend.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-139","question":"Two students both say Heinz should NOT steal the drug. Student P says, ‘He would be caught and put in jail.’ Student Q says, ‘If everyone broke the law whenever they felt justified, society would collapse.’ In Kohlberg’s scheme:","options":["Both are at the same stage because they reach the same decision","P is at Stage 1 and Q is at Stage 4","P is at Stage 2 and Q is at Stage 3","P is at Stage 4 and Q is at Stage 5"],"answer":1,"explanation":"Kohlberg classified the reasoning, not the decision. Fear of punishment marks Stage 1; maintaining social order through law marks Stage 4.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-140","question":"A Class 9 student keeps changing friend groups, hobbies and career plans, and often asks, ‘Who am I really?’ Her parents fear something is wrong. According to Erik Erikson, the teacher should explain that:","options":["This exploration is typical of the identity vs role confusion stage and, with support, helps her build a stable identity","She has regressed to the industry vs inferiority stage and needs remedial teaching","She is facing the intimacy vs isolation crisis, which normally belongs to adolescence","Her autonomy was not developed in early childhood, so the problem cannot now be corrected"],"answer":0,"explanation":"Trying out roles is the normal work of Erikson’s adolescent stage. Intimacy vs isolation belongs to young adulthood, and Erikson did not see earlier stages as permanently fixing later outcomes.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-141","question":"A Class 3 child is constantly compared with a ‘topper’ sibling and given tasks far beyond his ability, at which he keeps failing. Erikson’s theory warns that he is at risk of developing:","options":["Mistrust, from the trust vs mistrust stage","Guilt, from the initiative vs guilt stage","A sense of inferiority, from the industry vs inferiority stage","Role confusion, from the identity vs role confusion stage"],"answer":2,"explanation":"From about 6 to 12 years children judge themselves by their competence at tasks valued by school and peers; repeated failure and comparison breed inferiority. Achievable tasks and recognition of effort build industry.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-142","question":"Jerome Bruner claimed that any subject can be taught effectively in some intellectually honest form to any child at any stage of development. Which classroom implication follows from this claim?","options":["Complex ideas should be postponed until the child has reached the formal operational stage","Abstract symbols should be introduced as early as possible to speed up development","Each topic should be taught only once, in full depth, so that it need not be repeated","Key ideas can be introduced early in an enactive or iconic form and revisited later at greater depth in a spiral"],"answer":3,"explanation":"Bruner’s claim underlies the spiral curriculum: big ideas are introduced early in a form suited to the child and revisited with greater abstraction. Waiting for readiness is the position he was challenging.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-143","question":"To teach the water cycle, a teacher uses a song, a role-play of water drops, a labelled diagram and a group discussion on local rainfall. Which statement best reflects Howard Gardner’s theory in this case?","options":["The lesson offers several entry points to one concept, so children with different strengths can engage with it","The teacher should first find each child’s single learning style and teach that child only through it","Intelligence is one general ability, so the variety of activities only adds interest","Each child’s intelligences are fixed at birth, so the activities cannot develop them"],"answer":0,"explanation":"Gardner recommends teaching important ideas in several ways. He explicitly rejected equating multiple intelligences with ‘learning styles’ that restrict a child to one channel, and he saw intelligences as open to development.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-144","question":"Which of the following was NOT one of Howard Gardner’s criteria for accepting an ability as a separate intelligence?","options":["It can be isolated by brain damage, sparing other abilities","It has a distinct developmental history and an expert ‘end-state’ performance","It has an identifiable core operation or set of operations","It correlates highly with scores on standard IQ tests"],"answer":3,"explanation":"Gardner’s criteria include potential isolation by brain damage, a developmental history, core operations, existence of savants and prodigies, and encoding in a symbol system. A high correlation with IQ would argue against it being a separate intelligence.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-145","question":"A child believes that heavy things always sink. On a field trip she sees a large log floating, becomes puzzled, and after discussion begins to think that whether something floats depends on more than its weight. In Piaget’s terms, her puzzlement and her revised idea are respectively:","options":["Assimilation and equilibrium","Disequilibrium and accommodation","Accommodation and disequilibrium","Conservation and seriation"],"answer":1,"explanation":"The conflict between her schema and what she saw creates disequilibrium; changing the schema to fit the new experience is accommodation, which restores equilibrium.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-146","question":"Asked to find out what decides how fast a pendulum swings, a 14-year-old changes only the length while keeping the weight and the push the same, then tests each factor in turn. A 9-year-old changes the length and the weight together. The older child is showing:","options":["Seriation, which the younger child has not yet acquired","Class inclusion, typical of the concrete operational stage","Hypothetico-deductive reasoning with systematic isolation of variables, typical of formal operations","Object permanence, which allows her to remember the pendulum"],"answer":2,"explanation":"Testing one variable at a time to check hypotheses is the hallmark of formal operational thought (Inhelder and Piaget’s pendulum task). Concrete operational children tend to vary several factors at once.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-147","question":"A Class 5 child easily solves ‘Ravi is taller than Mohan and Mohan is taller than Sohan; who is the tallest?’ But told ‘Suppose all elephants were purple; Moti is an elephant, so what colour is Moti?’, he replies, ‘Elephants are grey, not purple.’ This best shows that:","options":["He is in the concrete operational stage: he reasons logically about real things but not from premises contrary to fact","He is still pre-operational, because he cannot use transitive reasoning","He has reached formal operations but is being careless","He lacks conservation, which is needed for any logical reasoning"],"answer":0,"explanation":"He handles transitivity (concrete operations) but cannot accept a hypothetical premise and reason from it, which needs formal operational thought.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-148","question":"Students forget new science terms within days when they just repeat them aloud, but remember them for weeks when they link each term to familiar examples and use it to explain events around them. According to the levels-of-processing view of Craik and Lockhart, this is because:","options":["Repetition moves information straight into long-term memory","Short-term memory has unlimited capacity when information is meaningful","Forgetting is caused only by the passage of time","Meaningful, elaborative processing creates deeper and more durable memory traces than shallow repetition"],"answer":3,"explanation":"Craik and Lockhart argued that retention depends on depth of processing; semantic elaboration produces stronger traces than maintenance rehearsal.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-149","question":"A child was repeatedly humiliated in front of the class during maths periods. Now she feels anxious as soon as she sees her maths textbook, even at home. In terms of classical conditioning:","options":["The textbook is the unconditioned stimulus and anxiety the unconditioned response","The humiliation is the conditioned stimulus and the textbook the unconditioned stimulus","The textbook has become a conditioned stimulus, and the anxiety it now triggers is a conditioned response","The anxiety is an operant behaviour that is being negatively reinforced"],"answer":2,"explanation":"Humiliation (UCS) naturally caused fear (UCR). Paired with it, the once-neutral textbook became a CS that alone now produces anxiety, a CR. Such conditioned anxiety is why classroom climate matters.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-150","question":"Whenever Manav disrupts the class, the teacher takes away ten minutes of his break time, and his disruptions decrease. In operant terms this is:","options":["Negative reinforcement","Negative punishment","Positive punishment","Extinction"],"answer":1,"explanation":"Removing something pleasant to reduce a behaviour is negative punishment. Negative reinforcement removes something unpleasant and increases a behaviour, a common mix-up.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-151","question":"A teacher decides to stop responding to a child who calls out answers without raising her hand. For the first few days the calling out becomes louder and more frequent. The teacher should understand that:","options":["This is an extinction burst, which is expected; if she stays consistent the behaviour should decline","Ignoring has failed, so she should go back to responding to the child","The child is being negatively reinforced by being ignored","This shows spontaneous recovery, which means the behaviour has been permanently learnt"],"answer":0,"explanation":"When a reinforcer is withdrawn, behaviour often intensifies briefly (an extinction burst). Giving in at this point reinforces the louder behaviour on an intermittent schedule and makes it harder to remove.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-152","question":"A teacher wants students to keep reading at home even after the class reward chart is withdrawn. Which pattern of rewards, while the chart is in use, is most likely to produce reading that resists extinction?","options":["A sticker for every single book read","A sticker exactly after every fifth book","A sticker on the last day of every month, whatever was read","A sticker after an unpredictable number of books, averaging one in four"],"answer":3,"explanation":"A variable-ratio schedule produces high, steady responding that is most resistant to extinction, because the learner cannot tell when the reward has stopped. Continuous reinforcement extinguishes fastest.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-153","question":"Simran is convinced she ‘can never do maths’. According to Bandura, which step would most strongly raise her self-efficacy in maths?","options":["Telling her repeatedly, ‘You are a bright girl, you can do it’","Letting her watch the class topper solve difficult problems","Giving her a graded series of tasks at which she genuinely succeeds, building up to harder ones","Excusing her from maths tests until she feels more confident"],"answer":2,"explanation":"Mastery experiences are the strongest source of self-efficacy. Verbal persuasion is weaker, and a model seen as very unlike oneself (the topper) has less effect than a similar model.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-154","question":"A child watches a folk dance closely and can describe every step accurately afterwards, wanting badly to perform it, but cannot yet coordinate her movements to do so. In Bandura’s model of observational learning, the breakdown is at the stage of:","options":["Attention","Motor reproduction","Retention","Motivation"],"answer":1,"explanation":"She attended and retained the steps, and she is motivated; what is missing is the physical ability to reproduce them. Practice with feedback is needed.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-155","question":"After seeing the teacher praise Rekha for her neat notebook in front of the class, several other children begin to keep their notebooks neat, though none of them has been praised yet. This is best explained by:","options":["Vicarious reinforcement","Classical conditioning","Insight learning","Negative reinforcement"],"answer":0,"explanation":"Seeing a model rewarded raises the observers’ expectation of reward, which Bandura called vicarious reinforcement.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-156","question":"A Class 4 student with low vision has joined a regular school. Which plan best reflects inclusive education under the RPwD Act, 2016?","options":["Recommend a special school, since the regular class may slow her down","Exempt her from written assessments so that she is not under pressure","Ask her to sit at the back so that she does not feel singled out","Seat her near the board with good lighting, give large-print or audio material, read aloud what is written and involve peers as partners"],"answer":3,"explanation":"Inclusion means adapting seating, materials and teaching so that the child learns in the regular class with reasonable accommodation, not segregating or exempting her.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-157","question":"In a lesson on plants, a teacher presents the content as a picture chart, a real potted plant to touch, an oral explanation and a short text with key words highlighted. Under Universal Design for Learning, she is mainly applying the principle of:","options":["Multiple means of engagement","Multiple means of action and expression","Multiple means of representation","Individualised remedial teaching"],"answer":2,"explanation":"Offering the same content in several forms (visual, tactile, auditory, text) is multiple means of representation. Letting children show learning in different ways would be action and expression.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-158","question":"A school admits children with disabilities into its regular classes but makes no change in teaching, materials, building or assessment; the children are expected to ‘cope like everyone else’. This situation is best described as:","options":["Inclusion, because the children study in the same classroom","Integration, because the child is placed in the mainstream but is expected to adjust to an unchanged system","Segregation, because the children are in a special unit","Mainstreaming with full reasonable accommodation"],"answer":1,"explanation":"Inclusion changes the system to fit every child; mere physical placement without accommodation is integration. The RPwD Act 2016 requires reasonable accommodation.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-159","question":"A school claims to follow continuous and comprehensive evaluation because it now holds a written unit test every week in every subject. The strongest criticism of this claim is that:","options":["It confuses ‘continuous’ with frequent testing; CCE means assessment woven into teaching through varied tools and also covers co-scholastic areas","Weekly tests are too few; CCE needs a test every day","CCE forbids any written test, so the school is breaking the rules","CCE is meant only for co-scholastic areas, so subject tests are irrelevant"],"answer":0,"explanation":"‘Continuous’ refers to ongoing assessment during learning (observation, projects, discussion, portfolios), and ‘comprehensive’ to scholastic and co-scholastic growth. More tests only add testing pressure.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-160","question":"After a writing task, students use a rubric to judge their own drafts, note what they need to improve, and set a target for the next draft. This is best described as:","options":["Assessment of learning","Summative assessment","Norm-referenced assessment","Assessment as learning"],"answer":3,"explanation":"When learners themselves monitor and regulate their learning through self-assessment, assessment becomes part of learning (assessment as learning), developing metacognition.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-161","question":"Which report on a Class 2 reading test is criterion-referenced?","options":["Riya scored higher than 80% of the children in her district","Riya reads 40 words per minute with 95% accuracy and meets the Grade 2 fluency benchmark","Riya ranked 3rd in her section","Riya’s score is one standard deviation above the class mean"],"answer":1,"explanation":"A criterion-referenced report compares performance with a fixed standard of what the child can do. Percentiles, ranks and standard scores compare her with other children (norm-referenced).","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-162","question":"A Class 4 maths test on multiplication uses long word problems written in difficult English. Many children who multiply well in class score poorly. The main problem with the test is its:","options":["Reliability, because the scores would change if the test were repeated","Objectivity, because different teachers would mark it differently","Validity, because it is partly measuring English reading rather than multiplication","Practicability, because it takes too long to administer"],"answer":2,"explanation":"A test is valid if it measures what it intends to. Here reading ability contaminates the score, so it is not a valid test of multiplication, even if it gives consistent results.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-163","question":"Studies show that identical twins reared apart have more similar intelligence test scores than unrelated children reared together, yet adopted children from deprived homes gain considerably when raised in enriched homes. The most defensible conclusion is:","options":["Heredity sets a range of potential, and the environment largely decides where within that range a child develops","Intelligence is fixed entirely by heredity","Intelligence is decided entirely by environment","Heredity and environment act separately, so their effects can simply be added"],"answer":0,"explanation":"Both findings together point to interaction: genes contribute substantially, but environment shapes how that potential is realised. Neither extreme position fits both findings.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-164","question":"A four-year-old, while playing with a friend, explains how to play a board game: ‘You put this here, then that goes there,’ pointing at pieces the friend cannot see from across the room. According to Piaget, this speech shows:","options":["Animism","Centration on a single dimension","Lack of object permanence","Egocentrism: difficulty taking another person’s point of view"],"answer":3,"explanation":"The child assumes the listener sees what she sees, so ‘this’ and ‘there’ seem clear to her. Piaget called this egocentric thought and speech.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-165","question":"A Class 3 textbook picture shows only mothers cooking and only fathers going to an office. The most appropriate response of a gender-sensitive teacher is to:","options":["Skip the picture so that the issue does not come up","Explain that this is how families naturally divide work","Ask children who does which work in their own homes, share examples of varied roles, and discuss whether any work belongs only to one gender","Tell the girls in the class that they will not have to cook when they grow up"],"answer":2,"explanation":"Drawing on children’s own experiences and discussing stereotypes helps them question fixed gender roles, as NCF 2005 urges. Ignoring or endorsing the picture leaves the stereotype unexamined.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-166","question":"At the start of the year a teacher is told (wrongly) that five randomly chosen children are ‘late bloomers’ about to make big gains. She gives them more attention, wait-time and encouragement, and by the year’s end they have indeed improved more than others. This illustrates:","options":["The halo effect","The Pygmalion effect (self-fulfilling prophecy)","Regression towards the mean","The Hawthorne effect"],"answer":1,"explanation":"Rosenthal and Jacobson showed that teachers’ expectations can change how they treat pupils and so shape achievement. This is why labelling children is harmful.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-167","question":"Children in a class love drawing in their free time. The school begins to give a prize for every drawing. Some weeks later the prizes are stopped, and the children now draw much less than they did before prizes began. The best explanation is that:","options":["The tangible rewards undermined the children’s intrinsic interest, so drawing came to feel like work done for a prize","The prizes were too small to make a lasting difference","The children have become better at drawing and no longer need practice","Drawing has been extinguished because it was never reinforced before"],"answer":0,"explanation":"Expected tangible rewards for an already enjoyable activity can reduce intrinsic motivation (the overjustification effect). Drawing was intrinsically motivated before the prizes, so the last option is wrong.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-168","question":"Before a difficult problem-solving test, a teacher tells the class that this test will ‘decide your whole future’. Students who were confident in practice now make careless errors on the hardest questions. According to the Yerkes–Dodson principle:","options":["Higher anxiety always improves performance, so the errors must be due to lack of preparation","Performance does not depend on arousal at all","Arousal improves performance on complex tasks but harms performance on simple ones","Performance is best at a moderate level of arousal, and for complex tasks the best level is lower, so very high anxiety hurts"],"answer":3,"explanation":"Performance rises with arousal up to an optimum and then falls; for difficult tasks the optimum is lower. The third option reverses the actual relationship.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-169","question":"Several children in a rural school come to school without breakfast and cannot concentrate in the first periods. In terms of Maslow’s hierarchy, the most logical first step is to:","options":["Meet their physiological needs, for example through the midday meal or a morning snack, before expecting attention to learning","Offer prizes to build their self-esteem","Give them more interesting lessons so that they want to learn for its own sake","Hold parent meetings about the importance of education"],"answer":0,"explanation":"Maslow held that lower (deficiency) needs such as hunger must be met before higher needs such as esteem and self-actualisation can guide behaviour.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-170","question":"Aman, aged 9, gives thoughtful oral answers in science discussions and does well in mental maths, but reads very slowly, guesses words from the first letter, and spells ‘was’ as ‘saw’ and ‘said’ as ‘sed’. The most likely explanation is:","options":["Intellectual disability, because his reading is far below his age","A specific learning disability in reading (dyslexia), since his difficulty is limited to decoding and spelling despite good reasoning","Laziness, since he can clearly answer well when he wants to","ADHD, since his reading errors show careless attention"],"answer":1,"explanation":"Average or better reasoning with a specific, unexpected difficulty in decoding and spelling fits dyslexia; intellectual disability would affect reasoning broadly. Labelling him lazy is a damaging misconception.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-171","question":"Which classroom strategy is most suitable for a child with ADHD?","options":["Giving long worksheets so that he learns to sit still for longer","Seating him near the window so that he can relax","Breaking tasks into short chunks with clear steps, building in brief movement breaks, and seating him near the teacher away from distractions","Ignoring all his work until he finishes a whole task without help"],"answer":2,"explanation":"Children with ADHD benefit from structure, short tasks, frequent feedback and chances to move. A seat by the window adds distraction, and long tasks set them up to fail.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-172","question":"A Class 2 child becomes very upset when the timetable changes without notice, rarely makes eye contact, and talks at length only about trains. Which support is most appropriate in an inclusive class?","options":["Insisting that she make eye contact while talking, so that she learns social skills","Changing her seat often so that she gets used to change","Avoiding her interest in trains, as it distracts her from the lesson","Using a visual daily schedule, warning her in advance of changes, and using her interest in trains to engage her in learning"],"answer":3,"explanation":"These traits suggest autism spectrum disorder. Predictable routines, visual supports and building on special interests reduce anxiety and aid learning; forced eye contact and sudden change raise distress.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-173","question":"Priya, a gifted Class 4 student, finishes class work early and is bored. Which of the following is an example of ENRICHMENT rather than acceleration?","options":["Promoting her straight to Class 5","Giving her another worksheet of similar sums each time she finishes","Asking her to investigate an open-ended question on the same topic in greater depth and present her findings","Letting her spend the extra time helping the teacher check other children’s notebooks"],"answer":2,"explanation":"Enrichment broadens and deepens learning at the same grade level through challenging, higher-order tasks. Grade skipping is acceleration, and more of the same is just busy work.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-174","question":"Children from a tribal community in a Class 1 classroom speak a language different from the school language and remain silent in class. Consistent with NEP 2020 and NCF 2005, the teacher should:","options":["Allow and use their home language in class as a bridge, while gradually building the school language","Insist on the school language only, so that they learn it faster","Seat them separately until they learn the school language","Tell parents to speak only the school language at home"],"answer":0,"explanation":"Both documents treat the home language as a resource; learning through it builds confidence and concepts, and supports the move to other languages. Banning it silences children.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-175","question":"Assertion (A): Piaget held that a child’s language reflects the concepts the child has already formed. Reason (R): For Piaget, cognitive development comes first and language develops on its basis.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Piaget saw language as dependent on thought: children use words for the concepts their cognitive structures allow. Vygotsky, by contrast, gave language a formative role in thought.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-176","question":"In a science activity, students must hang a lamp using a ruler, string and tape. Most of them say there is ‘nothing to use as a support’, because they see the ruler only as something for measuring. Their difficulty is called:","options":["Insight","Transfer of learning","Functional fixedness","Proactive interference"],"answer":2,"explanation":"Functional fixedness (Duncker) is the tendency to see an object only in its usual function, which blocks creative problem solving.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-177","question":"Before her exam, Neha lists the topics she does not yet understand, decides which to revise first, and after each session tests herself to see whether her plan is working. Neha is mainly using:","options":["Rote memorisation","Metacognition","Convergent thinking","Overlearning"],"answer":1,"explanation":"Planning, monitoring and evaluating one’s own learning is metacognition, a key aim of learner-centred teaching.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-178","question":"A Class 6 child says, ‘Plants get their food from the soil, that is why we put manure.’ A teacher following constructivist principles would most likely:","options":["Mark the answer wrong and dictate the correct definition of photosynthesis","Ignore the answer because the child will learn the correct idea in higher classes","Tell the class that the child is wrong and ask someone else","Ask the child to explain her reasoning and then plan experiences, such as comparing plants kept in light and dark, that let her test and revise her idea"],"answer":3,"explanation":"Constructivism treats a misconception as the child’s present idea; it should be surfaced and challenged through experience so that the child reconstructs it, not merely overwritten by a definition.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-179","question":"A teacher divides a lesson on the Indian monsoon into four parts. Each member of a home group studies one part with members of other groups who have the same part, then returns to teach it to the home group. Each student is tested on all four parts. This technique is:","options":["The jigsaw method of cooperative learning","Peer tutoring by a more able student","Programmed instruction","Brainstorming"],"answer":0,"explanation":"In Aronson’s jigsaw method each learner becomes an ‘expert’ on one piece, creating positive interdependence, since the group needs everyone’s part.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-180","question":"How many of the following statements about Kohlberg’s theory are correct? I. The stages follow an invariant sequence, so a stage cannot be skipped. II. Every adult eventually reaches Stage 6. III. Advanced moral reasoning requires a matching level of cognitive development, though cognitive development alone does not ensure it. IV. A person’s stage is decided by the action chosen in a dilemma.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and III are correct. Few people reach the post-conventional stages, and the stage is judged from the reasoning behind a choice, not the choice itself.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-181","question":"To help Class 1 children understand that the amount of water does not change when it is poured into a differently shaped glass, which approach would Piaget most strongly favour?","options":["Telling them the rule and asking them to memorise it","Showing a chart that explains conservation","Letting them pour water between containers of different shapes, predict, check and discuss what they notice","Rewarding children who give the correct answer until all of them say it"],"answer":2,"explanation":"Piaget saw children as active constructors of knowledge through action on materials; teaching a verbal rule or rewarding the answer gives a parroted response without the underlying operation.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-182","question":"Tanu began walking at 10 months and her cousin at 15 months; both are healthy and now walk equally well. Both crawled before they walked. Which principle of development do these facts illustrate together?","options":["Development is unpredictable in both sequence and rate","Development proceeds from specific responses to general ones","Later development depends entirely on early development","The sequence of development is similar for all children, but the rate varies from child to child"],"answer":3,"explanation":"Both crawled before walking (same sequence) but at different ages (different rate), the principle of individual differences within a common pattern.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-183","question":"NEP 2020 gives high priority to Early Childhood Care and Education. Its stated reason is that:","options":["Children must learn to read and write fluently before the age of three","Over 85% of a child’s cumulative brain development occurs before the age of six","Formal examinations should begin at the pre-school stage","Children below six cannot learn through play"],"answer":1,"explanation":"NEP 2020 notes that over 85% of cumulative brain development happens before age 6, so play-based, activity-based early learning is critical. It does not call for early formal reading or exams.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-184","question":"A teacher asks children to find out how much water their family uses in a day and to suggest ways of saving it, then uses their data in class. Which NCF 2005 guiding principle does this best reflect?","options":["Making examinations more flexible and integrated with classroom life","Enriching the curriculum so that it goes beyond textbooks","Connecting knowledge to life outside the school","Nurturing an overriding identity informed by caring concerns within the democratic polity"],"answer":2,"explanation":"Using children’s home experience as the basis of learning connects school knowledge with life outside school, the first of NCF 2005’s guiding principles.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-185","question":"Which piece of written feedback on a student’s essay is most effective for formative purposes?","options":["‘7/10. Good effort.’","‘Excellent! Keep it up.’","‘Your work is better than most of the class.’","‘Your opening states the issue clearly; in paragraph 3, give an example to support your claim about pollution, as you did in paragraph 2.’"],"answer":3,"explanation":"Effective formative feedback is specific, focuses on the task, and tells the learner how to close the gap. Marks, vague praise and comparisons with others give no direction for improvement.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-186","question":"The holistic progress card proposed in NEP 2020 is best described as:","options":["A report card showing only the marks scored in board-subject tests","A 360-degree, multidimensional report that includes self-assessment, peer assessment and teacher assessment of cognitive, affective and psychomotor growth","A record kept only by parents at home","A rank list comparing every child with the class average"],"answer":1,"explanation":"NEP 2020 proposes a 360-degree progress card covering all domains, with inputs from the child, peers and teacher, to show each learner’s progress and uniqueness.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-187","question":"In a subtraction test, 14 of 35 students write 82 − 46 = 44, and make similar errors in other sums that need regrouping. What should the teacher do first?","options":["Reteach the whole chapter to the entire class","Give these students more subtraction worksheets of the same type","Treat the result as a careless mistake and move on","Analyse the common error to diagnose the misconception (here, subtracting the smaller digit from the larger in each column), then plan remedial teaching for it"],"answer":3,"explanation":"A shared error pattern points to a shared misconception; diagnosis comes before remediation. 82 − 46 = 36, but taking 6 − 2 = 4 in the ones column and 8 − 4 = 4 in the tens gives 44.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-188","question":"Insulted by a classmate, Kavya notices her anger rising, takes a few deep breaths, and replies calmly. In Daniel Goleman’s model of emotional intelligence, she is mainly showing:","options":["Empathy","Social skill","Self-regulation (managing one’s emotions)","Motivation"],"answer":2,"explanation":"Recognising an emotion is self-awareness; controlling how one acts on it is self-regulation. Empathy concerns others’ feelings.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-189","question":"In Mary Ainsworth’s ‘strange situation’, a toddler shows little distress when the mother leaves and, when she returns, looks away and does not seek contact. This pattern is classified as:","options":["Insecure-avoidant attachment","Secure attachment","Insecure-resistant (ambivalent) attachment","Stranger anxiety, a normal sign of secure attachment"],"answer":0,"explanation":"A securely attached child is upset at separation and is comforted on reunion; ignoring or avoiding the mother on return marks the avoidant pattern.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-190","question":"Parents give their child whatever he asks for, rarely set rules or limits, and are very warm and affectionate. In Baumrind’s classification this is the:","options":["Authoritarian style","Authoritative style","Permissive (indulgent) style","Uninvolved (neglectful) style"],"answer":2,"explanation":"High warmth with low demands and control is permissive. Authoritative parents are warm but also set and explain limits; neglectful parents are low on both.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-191","question":"A three-year-old who has not had her afternoon nap insists, ‘It isn’t afternoon, because I haven’t had my nap.’ According to Piaget, this is an example of:","options":["Deductive reasoning","Inductive reasoning","Hypothetico-deductive reasoning","Transductive reasoning"],"answer":3,"explanation":"Transductive reasoning links one particular to another as if one caused the other (nap → afternoon), instead of reasoning from general to particular or particular to general.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-192","question":"Which statement correctly contrasts Piaget and Vygotsky on the relation between learning and development?","options":["Piaget held that learning leads development; Vygotsky held that development must come first","Piaget held that development sets limits that learning follows; Vygotsky held that good instruction runs ahead of development and leads it","Both held that development is entirely due to biological maturation","Both held that social interaction plays no part in cognitive growth"],"answer":1,"explanation":"For Piaget, what a child can learn depends on stage; for Vygotsky, instruction within the ZPD awakens functions that are maturing, so learning drives development.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-193","question":"A teacher keeps a running record of how each child participates in group work, notes the strategies children use, and adjusts the next day’s lesson accordingly. Which statement about this practice is correct?","options":["It is formative assessment, because the information is used to adapt teaching while learning is still going on","It is summative assessment, because it records children’s performance","It is not assessment at all, because no marks are given","It is norm-referenced assessment, because children are being compared"],"answer":0,"explanation":"Assessment is formative when its evidence is used to shape ongoing teaching and learning; marks are not needed, and the purpose, not the format, decides the type.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-194","question":"A teacher makes a restless Class 1 child copy the same row of letters again and again just before lunch, although the child’s hand is tired and he is not interested. The child becomes irritated and starts scribbling. Which of Thorndike’s laws best explains his reaction?","options":["Law of exercise","Law of effect","Law of readiness","Law of belongingness"],"answer":2,"explanation":"By the law of readiness, being forced to act when not ready is annoying. More drill (exercise) without readiness produces frustration, not learning.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-195","question":"Before a unit on the solar system, a teacher begins with a short overview: ‘Just as children in a ring game move around the person in the centre, planets move around the sun, each on its own path.’ According to David Ausubel, this introduction serves as:","options":["An advance organiser that links new material to what learners already know","A discovery task in which learners find the principle on their own","Negative reinforcement for attentive behaviour","A summative check of prior knowledge"],"answer":0,"explanation":"Ausubel’s advance organiser is a broad, introductory frame that anchors new information to existing cognitive structure, making it meaningful rather than rote.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-196","question":"To teach the concept ‘mammal’, a teacher includes a bat and a whale among her examples, and a penguin and a crocodile as non-examples. The main reason for choosing these is to:","options":["Make the lesson longer and more interesting","Test whether children have memorised the names of animals","Avoid any discussion of animals children already know","Sharpen the boundaries of the concept so that children neither overgeneralise (‘all flying things are birds’) nor undergeneralise (‘animals in water cannot be mammals’)"],"answer":3,"explanation":"Unusual examples and close non-examples force attention to the defining features (e.g. hair, feeding young on milk) rather than surface features such as habitat or flight.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-197","question":"A teacher reads out a list of 15 new words once. When children are asked to recall them, most remember the first few and the last few, but forget those in the middle. This is the:","options":["Zeigarnik effect","Serial position effect","Law of exercise","Spacing effect"],"answer":1,"explanation":"Recall is better for early items (primacy, more rehearsal) and late items (recency, still in short-term memory) than for middle items.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-198","question":"Two groups spend three hours in total revising the same chapter. Group A revises for three hours on the night before the test; Group B revises for 30 minutes on each of six days. A week after the test, Group B remembers much more. This supports the principle that:","options":["Massed practice is better for long-term retention","Total study time alone decides how much is remembered","Distributed (spaced) practice leads to better long-term retention than massed practice","Forgetting does not happen if the material is meaningful"],"answer":2,"explanation":"Spacing the same amount of practice over time strengthens retention, the spacing effect first shown by Ebbinghaus. Cramming may help briefly but is forgotten faster.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-199","question":"After learning a new set of spellings in English this week, Meena finds she can no longer recall some spellings she learnt last month. This is an example of:","options":["Proactive interference","Positive transfer","Repression","Retroactive interference"],"answer":3,"explanation":"Retroactive interference is when new learning disrupts the recall of older learning. Proactive interference works the other way, with old learning disrupting new.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-200","question":"Asked why he did not copy in the test, a Class 6 student says, ‘My teacher trusts me, and she would be so disappointed; I want her to think I am a good student.’ This reasoning belongs to Kohlberg’s:","options":["Pre-conventional level, Stage 2","Conventional level, Stage 3","Conventional level, Stage 4","Post-conventional level, Stage 5"],"answer":1,"explanation":"Seeking approval and wanting to be seen as ‘good’ by significant others marks Stage 3. Stage 4 would appeal to rules and order, Stage 2 to personal gain.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-201","question":"Piaget told children two stories: John accidentally broke 15 cups while opening a door; Henry broke one cup while trying to steal jam. A six-year-old says John is naughtier. This shows:","options":["Heteronomous morality, in which wrongdoing is judged by the amount of damage rather than by intention","Autonomous morality, in which intentions are weighed carefully","Kohlberg’s Stage 4 reasoning about law and order","Post-conventional reasoning about universal principles"],"answer":0,"explanation":"Young children in Piaget’s heteronomous stage (moral realism) judge by visible consequences; older children in the autonomous stage judge by intention and would call Henry naughtier.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-202","question":"A five-year-old keeps planning ‘shop’ and ‘doctor’ games and organising other children, but the teacher repeatedly calls her bossy and stops her games. According to Erikson, the child is at risk of developing a sense of:","options":["Shame and doubt","Inferiority","Guilt, in the initiative vs guilt stage","Mistrust"],"answer":2,"explanation":"In the preschool years children take initiative in planning and leading play; repeated criticism of such initiative can produce guilt. Inferiority belongs to the school-age stage.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-203","question":"A student keeps a reflective diary, knows her own strengths and weaknesses well, and sets realistic personal goals. In Gardner’s theory she shows high:","options":["Interpersonal intelligence","Existential intelligence","Linguistic intelligence","Intrapersonal intelligence"],"answer":3,"explanation":"Intrapersonal intelligence is understanding oneself, one’s feelings and motives. Interpersonal intelligence concerns understanding other people.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-204","question":"Asked for unusual uses of a brick, Rahul lists 20 uses, but every one is a kind of building or support (wall, step, doorstop, pillar…). Sana lists 8 uses that include a paperweight, a weapon, a weight for exercise and crushed red powder for colour. Which statement is correct?","options":["Rahul is higher in both fluency and flexibility","Sana is higher in fluency; Rahul is higher in originality","Rahul is higher in fluency, while Sana is higher in flexibility","Both are equal in creativity, because creativity is measured only by the total number of ideas"],"answer":2,"explanation":"Fluency is the number of ideas; flexibility is the number of different categories. Rahul’s many ideas fall in one category, while Sana’s fewer ideas cover several categories.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-205","question":"An intelligence test standardised on urban children asks, ‘What do you do when an escalator stops?’ Rural children who have never seen an escalator score lower on it. The main problem is that the test:","options":["Is culturally biased, so it measures familiarity with a particular environment rather than ability","Is too reliable for rural children","Measures emotional intelligence instead of general intelligence","Shows that rural children have lower intelligence"],"answer":0,"explanation":"Items that depend on specific cultural experience disadvantage children who lack it; the score reflects exposure, not intelligence. Culture-fair tests try to reduce this.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-206","question":"On a modern deviation-IQ test with a mean of 100 and a standard deviation of 15, a child scores 130. Assuming a normal distribution, which statement is correct?","options":["The child’s mental age is 30% higher than her chronological age","The child scored 30% more marks than an average child","The child is in the ‘very superior’ range only if her chronological age is above 10","The child scored two standard deviations above the mean, higher than roughly 97–98% of her age group"],"answer":3,"explanation":"130 = 100 + 2 × 15. About 2.3% of a normal distribution lies above +2 SD. A deviation IQ compares a child with same-age peers; it is not a mental-age ratio or a percentage of marks.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-207","question":"Under the Rights of Persons with Disabilities Act, 2016, ‘reasonable accommodation’ means:","options":["Admitting a child with a disability only if she can follow the regular class without help","Necessary and appropriate modification and adjustments, not imposing a disproportionate or undue burden, to ensure a person with a disability can exercise rights equally with others","Providing a separate special school close to the child’s home","Reducing the syllabus for all children in a class that has a child with a disability"],"answer":1,"explanation":"The Act defines reasonable accommodation as appropriate modifications and adjustments, without undue burden, to ensure equal enjoyment of rights; examples are ramps, scribes, extra time and accessible materials.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-208","question":"A mother’s employer suddenly changes her working hours to a late shift, so she can no longer help her son with homework, and his work suffers. In Bronfenbrenner’s ecological model, the mother’s workplace is part of the child’s:","options":["Microsystem","Mesosystem","Exosystem","Macrosystem"],"answer":2,"explanation":"The exosystem includes settings the child does not take part in directly but that affect him, such as a parent’s workplace. The mesosystem links two of the child’s own settings, such as home and school.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-209","question":"A 14-year-old refuses to go to school because of a small pimple, convinced that ‘everyone will be staring at me all day’. David Elkind called this form of adolescent egocentrism the:","options":["Imaginary audience","Personal fable","Identity foreclosure","Psychosocial moratorium"],"answer":0,"explanation":"The imaginary audience is the belief that one is the focus of everyone’s attention. The personal fable is the belief that one’s experiences are unique and that one is invulnerable.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-210","question":"A student learning to type improves steadily for three weeks, then shows no improvement for ten days in spite of practice, and later starts improving again. The flat period is best described as:","options":["Extinction of the learned skill","Forgetting due to disuse","Negative transfer of training","A plateau in the learning curve"],"answer":3,"explanation":"A plateau is a temporary flat stretch in a learning curve, often caused by fatigue, loss of motivation, or the need to reorganise a skill at a higher level; it does not mean learning has stopped for good.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-211","question":"A teacher assesses a science project with a tool that lists criteria (planning, data, explanation, presentation) and, for each criterion, describes what ‘beginning’, ‘developing’ and ‘proficient’ work looks like. This tool is a:","options":["Checklist","Rubric","Anecdotal record","Cumulative record"],"answer":1,"explanation":"A rubric pairs criteria with descriptions of performance at each level. A checklist records only whether a feature is present or absent.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-212","question":"During recess a teacher notices a usually shy child comforting a younger child who has fallen, and later writes a brief, factual note of what happened, with the date. This record is called:","options":["A rating scale","A cumulative record","An anecdotal record","A sociogram"],"answer":2,"explanation":"An anecdotal record is a short, objective description of a significant incident in a child’s behaviour, useful for assessing personal and social qualities.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-213","question":"Which question targets the ‘evaluating’ level of Bloom’s revised taxonomy?","options":["Name two methods of purifying water.","Explain why boiling makes water safe to drink.","Use a filter to clean a sample of muddy water.","Which of the two methods, boiling or filtering, would you recommend for your village, and why?"],"answer":3,"explanation":"Evaluating means making and justifying a judgement against criteria. Naming is remembering, explaining is understanding, and using a filter is applying.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-214","question":"A teacher who knows that a student comes from a well-off family and has neat handwriting gives his essay higher marks than another essay of equal quality. This is an example of:","options":["The halo effect","The central tendency error","The recency effect","Criterion-referenced marking"],"answer":0,"explanation":"The halo effect is when one favourable impression (neatness, background) colours the judgement of unrelated qualities. Clear rubrics and anonymous marking reduce it.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-215","question":"A 22-month-old says ‘Daddy go car’ and ‘more juice’. This stage of language development is called:","options":["Babbling","Holophrastic speech","Telegraphic speech","Cooing"],"answer":2,"explanation":"Two- or three-word utterances keeping the key content words and dropping function words are telegraphic speech. Holophrastic speech uses single words for whole ideas.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-216","question":"According to Vygotsky, the order in which speech develops in relation to thought is:","options":["Inner speech → private speech → social speech","Private speech → social speech → inner speech","Social speech → inner speech → private speech","Social speech → private speech → inner speech"],"answer":3,"explanation":"Speech first serves to communicate with others, is then turned on oneself aloud as private speech to guide action, and finally goes ‘underground’ as silent inner speech, a tool of thought.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-217","question":"In a science lesson the teacher gives students magnets and various objects, asks, ‘What kinds of things does a magnet attract?’, and lets them test, record and find the pattern themselves, stepping in with questions only when needed. This approach is most closely linked with:","options":["Bruner’s discovery learning","Skinner’s programmed learning","Pavlov’s classical conditioning","Thorndike’s trial-and-error learning by drill"],"answer":0,"explanation":"Bruner advocated discovery learning, in which learners find principles through active exploration with guidance; it builds understanding and transfer.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-218","question":"Which of the following statements about adolescent peer groups is most accurate for a teacher planning classroom activities?","options":["Peers have no influence once children reach adolescence, because family influence dominates","Peer influence is always negative and should be kept out of the classroom","Peer acceptance becomes very important to adolescents, so structured group work and peer roles can be used positively for learning","Adolescents learn best working alone because they are egocentric"],"answer":2,"explanation":"Need for belonging and peer approval rises in adolescence; it can lead to conformity, but well-planned cooperative tasks channel it towards learning and social skills.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-219","question":"A Class 2 teacher notices that a child who learnt to count objects by tens in maths now groups items in tens on her own while sorting seeds in EVS. The teacher is seeing:","options":["Negative transfer","Positive transfer of learning","Retroactive interference","Spontaneous recovery"],"answer":1,"explanation":"Learning in one setting that helps performance in another is positive transfer. Teaching for understanding and showing links across subjects promotes it.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-220","question":"Assertion (A): According to Vygotsky, cultural tools such as language, number systems and writing shape the way children think. Reason (R): Vygotsky held that higher mental functions first appear between people and are then internalised by the individual.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Vygotsky’s ‘general genetic law’ says every function appears twice, first socially and then individually; because cultural tools are used socially before being internalised, they come to shape thought.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-221","question":"How many of these statements about formative and summative assessment are correct? I. The same test can be formative or summative depending on how its results are used. II. Summative assessment usually comes at the end of a unit or term. III. Formative assessment must always be oral. IV. Formative assessment is mainly for improving learning, while summative is mainly for certifying it.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. Formative assessment can take many forms, written quizzes, observation, drafts, peer review, not only oral questioning.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-222","question":"A Class 5 child often hits other children. When the teacher shouts at him and gives a slap in anger, the hitting does not stop and he begins hitting younger children more often. Social learning theory best explains this because:","options":["Punishment always increases a behaviour","The child is being negatively reinforced by the teacher","The child’s hitting is due to heredity and cannot be changed","The teacher is modelling aggression as a way of dealing with problems, which the child imitates"],"answer":3,"explanation":"Bandura showed that children imitate aggressive models, especially powerful adults. Corporal punishment is also banned under Section 17 of the RTE Act.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-223","question":"An 18-month-old who saw a cousin throw a tantrum yesterday stamps her feet and screams in exactly the same way today, with the cousin nowhere around. For Piaget, this deferred imitation is important because it shows:","options":["That the child is still at the stage of reflex actions","The beginning of mental representation, marking the transition out of the sensorimotor stage","That the child has acquired conservation","That the behaviour was learnt through classical conditioning"],"answer":1,"explanation":"Imitating a model who is no longer present requires a stored mental image; Piaget took this as evidence of emerging symbolic thought at the end of the sensorimotor period.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-224","question":"A four-year-old rides a stick as a ‘horse’ and, while playing ‘school’, sits still far longer than she does in real class. From Vygotsky’s viewpoint, the main developmental value of such pretend play is that it:","options":["Lets the child escape from rules altogether","Is only a way of releasing surplus energy","Separates meaning from real objects and makes the child follow the rules of a role, creating a zone of proximal development in which she behaves ‘a head taller’ than herself","Shows that the child is still egocentric and should be moved on to formal tasks"],"answer":2,"explanation":"Vygotsky saw make-believe play as a leading activity: substituting objects frees thought from things, and keeping to role rules builds self-regulation beyond the child’s everyday level.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-225","question":"To teach a child with a mild intellectual disability to wash his hands properly, the teacher breaks the skill into small steps (wet hands, apply soap, rub palms, rub backs, rinse, dry), teaches each step with demonstration and praise, and links them together. This approach is called:","options":["Task analysis","Brainstorming","Discovery learning","Programmed failure"],"answer":0,"explanation":"Task analysis breaks a complex skill into small, sequenced steps that are taught and reinforced one by one, a key strategy for learners with intellectual disabilities.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-226","question":"Varun asks unusually deep questions in class discussions and solves puzzles quickly, but rarely finishes written work, scores poorly and often disturbs others. A thoughtful teacher should first consider that he may be:","options":["A slow learner who needs simplified tasks","A child with an intellectual disability","A child who is simply indisciplined and needs stricter punishment","A gifted underachiever who is bored by unchallenging work and needs more stimulating tasks"],"answer":3,"explanation":"High reasoning ability with poor performance and disruptive boredom is a classic profile of gifted underachievement; challenge and engagement, not simplification or punishment, address it.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-227","question":"A teacher always asks boys to move benches and girls to decorate the notice board and serve water to guests. She never states any view on gender. Through these routine practices, children are learning gender roles via the:","options":["Formal curriculum","Hidden curriculum","Spiral curriculum","Co-scholastic curriculum"],"answer":1,"explanation":"The hidden curriculum is the unstated lessons conveyed by routines, expectations and practices; here it quietly teaches stereotyped gender roles.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-228","question":"Which remark from a student best shows a mastery (learning) goal orientation rather than a performance goal orientation?","options":["‘I chose the easy questions so that I would not look stupid in front of the class.’","‘I picked the hard problem because I want to really understand how fractions work, even if I get it wrong at first.’","‘I want to score more than Rohit in this test.’","‘I only study for topics that come in the exam.’"],"answer":1,"explanation":"Mastery goals focus on understanding and improving; performance goals focus on looking competent or beating others, and often lead learners to avoid challenge.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-229","question":"After failing a test, a student says, ‘I am just not a maths person.’ Using Weiner’s attribution theory, the teacher would most help her by encouraging her to attribute the failure to:","options":["Bad luck, which is external and uncontrollable","The difficulty of the test, which is external and stable","Low ability, which is internal and stable","Insufficient effort or an ineffective strategy, which are internal but changeable and controllable"],"answer":3,"explanation":"Attributing failure to stable, uncontrollable causes such as ability lowers persistence; attributing it to effort or strategy, which the student can change, keeps motivation alive.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-230","question":"After failing repeatedly in maths and being scolded each time, a Class 5 child now does not even try the easy sums and says, ‘What’s the use? I’ll get it wrong anyway.’ This condition is best described as:","options":["Learned helplessness","Intrinsic motivation","Functional fixedness","Self-actualisation"],"answer":0,"explanation":"Seligman described learned helplessness: after repeated experiences of uncontrollable failure a person stops trying even when success is possible. Small, assured successes help to break it.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-231","question":"A teacher who used to call on a student within a second of asking a question begins waiting three to five seconds before taking an answer. According to research on wait time, the most likely effect is:","options":["Students lose interest and the class becomes noisy","More students attempt answers, and answers become longer and more thoughtful","Only the fastest students answer, as before","Students answer less, because silence makes them anxious"],"answer":1,"explanation":"Mary Budd Rowe found that a longer wait time leads to more students responding, longer and better-reasoned answers, and more questions from students.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-232","question":"How many of these statements about growth and development are correct? I. Growth refers mainly to quantitative changes such as height and weight. II. Development includes qualitative changes in functioning. III. Growth in height continues throughout life. IV. Development can continue even after physical growth stops.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. Growth in height stops after adolescence, but development (in thinking, skills and personality) continues throughout life.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-233","question":"According to Freud, the period from about six years to puberty, when children’s energy is directed mainly towards school learning, skills and same-sex friendships, is the:","options":["Phallic stage","Anal stage","Genital stage","Latency stage"],"answer":3,"explanation":"Freud’s latency stage covers the primary school years, when sexual impulses are relatively dormant and energy goes into learning and friendships. It roughly matches Erikson’s industry vs inferiority stage.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-234","question":"In a crèche, one caregiver responds promptly and warmly to an infant’s cries, while in another, infants are fed and changed at irregular times and their crying is often ignored. According to Erikson, infants in the second crèche are more likely to develop:","options":["A basic sense of mistrust towards the world","A sense of guilt about their own actions","A sense of inferiority","Role confusion"],"answer":0,"explanation":"Erikson’s first stage (trust vs mistrust) depends on consistent, responsive care; unpredictable or neglectful care breeds mistrust.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-235","question":"Under NEP 2020’s 5+3+3+4 structure, a 12-year-old in Grade 7 is in which stage, and what is the recommended emphasis?","options":["Preparatory stage; play-based learning with light textbooks","Middle stage; experiential learning in the sciences, mathematics, arts, social sciences and humanities, with subject teachers","Secondary stage; multidisciplinary study with choice of subjects and greater critical thinking","Foundational stage; flexible, multilevel, activity-based learning"],"answer":1,"explanation":"The Middle stage covers Grades 6–8 (ages about 11–14) and introduces subject teachers and more abstract concepts through experiential learning. Grades 3–5 form the Preparatory stage and 9–12 the Secondary stage.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-236","question":"NCF 2005’s concern about heavy school bags, rote learning and exam stress drew on which earlier report?","options":["The Kothari Commission report, 1966","The Mudaliar Commission report, 1953","‘Learning Without Burden’, the Yash Pal Committee report, 1993","The Radhakrishnan Commission report, 1949"],"answer":2,"explanation":"The Yash Pal Committee’s ‘Learning Without Burden’ (1993) identified the burden of non-comprehension as a key problem, and NCF 2005 built on it.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-237","question":"Studies in several collectivist societies found that adults who reasoned mainly in terms of duties to family and community were often scored at Kohlberg’s Stage 3 or 4, rarely higher. This finding is mainly used to argue that Kohlberg’s scheme:","options":["Proves that people in those societies are morally less developed","Shows that moral reasoning does not develop with age","Is a theory of emotions, not of moral reasoning","May be culturally biased, privileging individual rights and justice reasoning typical of Western societies"],"answer":3,"explanation":"Critics argue that the highest stages reflect an individualistic, justice-based ideal; community-oriented moral reasoning may be mature in its own terms but is underscored.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-238","question":"In Martin Hughes’s ‘policeman doll’ task, many children aged about 3½ to 5 could hide a doll where two ‘policemen’ could not see it, though most failed Piaget’s three-mountains task. The finding is used to argue that:","options":["Piaget overestimated the abilities of young children","Young children can take another’s perspective when the task makes human sense to them, so Piaget underestimated them","Egocentrism lasts until the formal operational stage","Perspective taking depends only on language ability"],"answer":1,"explanation":"Hughes showed that in a meaningful, familiar context young children can decentre; the abstract mountains task masked their competence, a common critique of Piaget.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-239","question":"NEP 2020 calls for board examinations to be reformed mainly so that they:","options":["Test core capacities and competencies rather than months of coaching and memorisation","Are held every month instead of once a year","Are made harder so that fewer students pass","Test only objective, factual recall that is easy to mark"],"answer":0,"explanation":"NEP 2020 wants board exams to be ‘easier’ in the sense of testing core concepts and competencies, reducing the need for coaching and rote learning.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-240","question":"The same essay is given 8/20 by one examiner and 16/20 by another. The main weakness this reveals is in the test’s:","options":["Content validity","Predictive validity","Scoring reliability (objectivity)","Norm-referencing"],"answer":2,"explanation":"When different scorers give very different marks to the same answer, the scoring is unreliable. Rubrics and moderation improve inter-rater reliability; validity concerns whether the right thing is measured.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-241","question":"A music school gives applicants a test to predict how well they would do if trained, though most have never studied music. This is:","options":["An achievement test","A diagnostic test","An attitude scale","An aptitude test"],"answer":3,"explanation":"An aptitude test predicts potential to learn a skill with training. An achievement test measures what has already been learnt, and a diagnostic test finds specific difficulties.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-242","question":"Each child in a class names two classmates they would most like to work with. The teacher draws the choices as arrows. One child receives no arrows from anyone. The tool and the child’s position are respectively:","options":["A sociogram; an isolate","A rating scale; a star","A cumulative record; a leader","A projective test; a rejectee"],"answer":0,"explanation":"Sociometry (Moreno) uses peer choices drawn as a sociogram; a child chosen by none is an isolate, while one chosen by many is a star.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-243","question":"In a Montessori class, a child tries to fit wooden cylinders into holes of matching sizes. If one goes into the wrong hole, the last cylinder will not fit, so the child sees the mistake without being told. This feature reflects Montessori’s principle of:","options":["Reinforcement by the teacher","Auto-education through self-correcting didactic material","Learning by rote repetition","Group competition"],"answer":1,"explanation":"Montessori’s materials have a built-in ‘control of error’, letting the child discover and correct mistakes independently, the idea of auto-education.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-244","question":"Class 6 students run a small school stationery shop, keeping accounts, ordering stock and dividing duties, and learn maths and social skills through it. This reflects John Dewey’s view that:","options":["Learning should be mainly through lectures and textbooks","Children should be kept away from real-life responsibilities","The school should be a miniature society where learning grows out of purposeful activities","Discipline is best taught through rewards and punishments"],"answer":2,"explanation":"Dewey saw the school as an embryonic community in which children learn by doing purposeful, social activities connected to life.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-245","question":"Which classroom practice is most distinctively social constructivist (Vygotskian) rather than individual cognitive constructivist (Piagetian)?","options":["A child working alone with materials to discover a rule","The teacher giving a lecture followed by individual practice","A child being rewarded for each correct answer","Small groups arguing about competing explanations, building on one another’s ideas to reach a shared understanding"],"answer":3,"explanation":"Both see learners as active, but social constructivism places the source of understanding in dialogue and joint activity with others. Lone discovery fits Piaget; rewards fit behaviourism.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-246","question":"How many of these ideas are consistent with behaviourism? I. Learning is a change in observable behaviour. II. Reinforcement strengthens the behaviour it follows. III. Learners actively construct meaning from experience. IV. Complex behaviour can be built by reinforcing successive approximations.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are behaviourist. Active construction of meaning is a constructivist idea that behaviourism leaves out.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-247","question":"A very withdrawn child never speaks in class. The teacher first praises her for looking at the speaker, then only when she raises her hand, then only when she says a word, and finally only when she gives a full answer. This technique is called:","options":["Shaping","Chaining of reflexes","Extinction","Modelling"],"answer":0,"explanation":"Shaping reinforces successive approximations of the target behaviour, raising the requirement step by step (Skinner).","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-child-development-248","question":"A child in Class 3 stammers when answering. What should the teacher do?","options":["Complete the words for him to save time","Tell him to speak faster and more confidently","Listen patiently, maintain natural eye contact, avoid finishing his sentences and discourage peers from mocking","Exempt him from all oral activities"],"answer":2,"explanation":"Patience and an accepting class reduce the anxiety that worsens stammering; finishing words, hurrying him or excluding him from speaking all lower confidence.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-child-development-249","question":"A teacher tells a student caught bullying, ‘I don’t accept what you did, and there will be consequences, but I still value you and believe you can do better.’ This reflects Carl Rogers’s idea of:","options":["Conditional regard","Negative reinforcement","Authoritarian control","Unconditional positive regard"],"answer":3,"explanation":"Rogers held that accepting the person while disapproving of a behaviour supports a healthy self-concept and growth; regard tied to good behaviour is conditional.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-child-development-250","question":"Which statement about emotion and learning is best supported by research and by NCF 2005?","options":["A safe, supportive emotional climate aids attention, memory and risk-taking in learning, while chronic fear and anxiety impair them","Emotions are irrelevant to learning, which is a purely cognitive process","Fear of punishment is the most effective way to keep children attentive","Emotions matter only in co-scholastic activities such as sports and music"],"answer":0,"explanation":"Emotion and cognition are intertwined: anxiety narrows attention and hampers working memory, while a secure classroom encourages questioning and exploration.","difficulty":"hard","source":"CTET · State TETs"},
];

export default questions;
